import Foundation

enum QuoteData {
    static let allQuotes: [Quote] = quotes_1 + quotes_2 + quotes_3 + quotes_4 + quotes_5 + quotes_7 + quotes_modern + quotes_batch_a + quotes_batch_b + quotes_batch_c + quotes_batch_d + quotes_batch_e + quotes_batch_f + quotes_batch_h + quotes_batch_i + quotes_batch_j + quotes_batch_k + quotes_batch_l

    /// 去重后的语录（按 text 去重，保留首次出现）
    static let uniqueQuotes: [Quote] = {
        var seen = Set<String>()
        return allQuotes.filter { quote in
            if seen.contains(quote.text) { return false }
            seen.insert(quote.text)
            return true
        }
    }()

    /// 分类归一化：将古代典籍语录按作者/来源合并大类
    static func normalizedCategory(for quote: Quote) -> String {
        let author = quote.author
        // 古代典籍统一分类
        switch author {
        case "老子": return "道德经"
        case "孔子", "曾子", "子夏", "子贡", "有子", "子禽", "子路", "颜渊", "颜回", "仲弓", "冉求", "宰我", "樊迟":
            return "论语"
        case "孟子": return "孟子"
        case "庄子", "庄周": return "庄子"
        case "荀子": return "荀子"
        case "墨子": return "墨子"
        case "韩非子": return "韩非子"
        case "屈原": return "楚辞"
        case "司马迁", "班固", "司马光", "陈寿": return "史书"
        case "《周易》", "《诗经》", "《尚书》", "《礼记》", "《左传》", "《国语》", "《战国策》":
            return "先秦经典"
        case "《警世贤文》", "中国谚语", "俗语", "古语", "古训":
            return "谚语古训"
        case "诸葛亮", "曹操", "文天祥", "于谦", "林则徐", "王勃", "郑板桥", "颜真卿":
            return "古代名句"
        case "苏轼", "李白", "杜甫", "白居易", "王维", "陶渊明", "辛弃疾", "陆游",
             "王安石", "刘禹锡", "孟浩然", "李商隐", "杜牧", "李清照", "柳永",
             "欧阳修", "韩愈", "柳宗元", "范仲淹", "杨炯", "卢照邻", "骆宾王",
             "高适", "岑参", "王昌龄", "王之涣", "贺知章", "张九龄", "曹植",
             "嵇康", "阮籍":
            return "古诗词"
        case "鲁迅", "冰心", "巴金", "老舍", "茅盾", "朱自清", "郁达夫", "徐志摩",
             "林语堂", "梁实秋", "丰子恺", "汪曾祺", "史铁生", "余华", "莫言",
             "席慕蓉", "三毛", "周国平", "王小波":
            return "近现代文学"
        case "毛泽东":
            return "毛选诗词"
        case "黄蘖禅师", "慧能", "玄奘", "弘一法师", "星云大师":
            return "禅意智慧"
        case "温斯顿·丘吉尔", "顾拜旦", "爱因斯坦", "爱迪生", "列夫·托尔斯泰",
             "奥斯特洛夫斯基", "海伦·凯勒", "居里夫人", "牛顿", "伽利略",
             "贝多芬", "莫扎特", "莎士比亚", "歌德", "尼采", "苏格拉底",
             "柏拉图", "亚里士多德", "罗曼·罗兰", "雨果", "巴尔扎克",
             "狄更斯", "海明威", "马克·吐温", "卡耐基", "拿破仑·希尔",
             "乔布斯", "马斯克", "比尔·盖茨", "扎克伯格", "贝佐斯",
             "巴菲特", "芒格", "富兰克林", "林肯", "罗斯福", "戴高乐",
             "蒙田", "卡夫卡", "黑塞", "纪伯伦", "泰戈尔", "村上春树",
             "稻盛和夫", "松下幸之助", "盛田昭夫":
            return "外国名人"
        default:
            break
        }

        // 现代语录（分类含特定关键词）保持原样
        let modernKeywords = ["都市", "职场", "自我", "时间", "心态", "梦想", "生活",
                              "人际", "坚持", "勇气", "专注", "感恩", "现代", "行动", "独处",
                              "学习", "思考", "认知", "创造"]
        if modernKeywords.contains(where: { quote.category.contains($0) }) {
            return quote.category
        }

        // 其余统一合并
        return "励志名言"
    }

    /// 获取所有归一化分类
    static var allCategories: [String] {
        let cats = Set(uniqueQuotes.map { normalizedCategory(for: $0) })
        return cats.sorted()
    }

    /// 按归一化分类筛选
    static func quotesInCategory(_ category: String?) -> [Quote] {
        guard let category else { return uniqueQuotes }
        return uniqueQuotes.filter { normalizedCategory(for: $0) == category }
    }
    
    private static let quotes_1: [Quote] = [
        Quote(text: "成功不是终点，失败也不是致命的，重要的是继续前进的勇气。", author: "温斯顿·丘吉尔", category: "勇气与坚持", translation: "Success is not final, failure is not fatal: it is the courage to continue that counts."),
        Quote(text: "生活中最重要的事情不是胜利，而是奋斗；不是征服，而是努力拼搏。", author: "顾拜旦", category: "奋斗与拼搏", translation: "The most important thing in life is not the triumph but the struggle; not to have conquered but to have fought well."),
        Quote(text: "千里之行，始于足下。", author: "老子", category: "行动与开始"),
        Quote(text: "天将降大任于斯人也，必先苦其心志，劳其筋骨。", author: "孟子", category: "磨难与成长"),
        Quote(text: "宝剑锋从磨砺出，梅花香自苦寒来。", author: "《警世贤文》", category: "磨难与成长"),
        Quote(text: "世上无难事，只怕有心人。", author: "中国谚语", category: "坚持与毅力"),
        Quote(text: "不经一番寒彻骨，怎得梅花扑鼻香。", author: "黄蘖禅师", category: "磨难与成长"),
        Quote(text: "路漫漫其修远兮，吾将上下而求索。", author: "屈原", category: "探索与追求"),
        Quote(text: "天行健，君子以自强不息。", author: "《周易》", category: "自强与奋斗"),
        Quote(text: "志当存高远。", author: "诸葛亮", category: "志向与目标"),
        Quote(text: "志不强者智不达。", author: "墨子", category: "意志与智慧"),
        Quote(text: "穷且益坚，不坠青云之志。", author: "王勃", category: "困境与志向"),
        Quote(text: "老骥伏枥，志在千里；烈士暮年，壮心不已。", author: "曹操", category: "志向与坚持"),
        Quote(text: "咬定青山不放松，立根原在破岩中。千磨万击还坚劲，任尔东西南北风。", author: "郑板桥", category: "坚持与坚韧"),
        Quote(text: "古之立大事者，不惟有超世之才，亦必有坚忍不拔之志。", author: "苏轼", category: "立志与成才"),
        Quote(text: "人生自古谁无死，留取丹心照汗青。", author: "文天祥", category: "气节与人生"),
        Quote(text: "粉身碎骨浑不怕，要留清白在人间。", author: "于谦", category: "气节与品格"),
        Quote(text: "海纳百川，有容乃大；壁立千仞，无欲则刚。", author: "林则徐", category: "胸怀与品格"),
        Quote(text: "苟利国家生死以，岂因祸福避趋之。", author: "林则徐", category: "责任与担当"),
        Quote(text: "横眉冷对千夫指，俯首甘为孺子牛。", author: "鲁迅", category: "品格与奉献"),
        Quote(text: "其实地上本没有路，走的人多了，也便成了路。", author: "鲁迅", category: "探索与开创"),
        Quote(text: "时间就像海绵里的水，只要愿挤，总还是有的。", author: "鲁迅", category: "时间与珍惜"),
        Quote(text: "哪里有天才，我是把别人喝咖啡的工夫都用在工作上的。", author: "鲁迅", category: "勤奋与努力"),
        Quote(text: "人生的价值，并不是用时间，而是用深度去衡量的。", author: "列夫·托尔斯泰", category: "人生价值", translation: "The value of life is not measured by time, but by depth."),
        Quote(text: "人最宝贵的是生命，生命对每个人只有一次。", author: "奥斯特洛夫斯基", category: "生命与珍惜", translation: "Man's dearest possession is life. It is given to him but once."),
        Quote(text: "人的一生应当这样度过：当回忆往事的时候，他不会因为虚度年华而悔恨，也不会因为碌碌无为而羞愧。", author: "奥斯特洛夫斯基", category: "人生意义", translation: "Man's life should be spent like this: when he recalls the past, he will not regret wasting his years, nor feel ashamed of doing nothing."),
        Quote(text: "世界上最快乐的事，莫过于为理想而奋斗。", author: "苏格拉底", category: "理想与奋斗", translation: "The happiest thing in the world is to struggle for an ideal."),
        Quote(text: "最困难的事情就是认识自己。", author: "泰勒斯", category: "自我认知"),
        Quote(text: "未经审视的人生不值得过。", author: "苏格拉底", category: "人生思考", translation: "The unexamined life is not worth living."),
        Quote(text: "智者说话，是因为他们有话要说；愚者说话，则是因为他们想说。", author: "柏拉图", category: "智慧与言语", translation: "Wise men speak because they have something to say; fools speak because they have to say something."),
        Quote(text: "优秀是一种习惯。", author: "亚里士多德", category: "习惯与优秀", translation: "Excellence is a habit."),
        Quote(text: "人生最终的价值在于觉醒和思考的能力，而不只在于生存。", author: "亚里士多德", category: "人生价值", translation: "The ultimate value of life lies in the power to awaken and think, not just to survive."),
        Quote(text: "真正的勇敢，是在你还没开始的时候就知道自己注定会输，但依然义无反顾地去做，并且不管发生什么都坚持到底。", author: "哈珀·李", category: "勇气与坚持"),
        Quote(text: "你要搞清楚自己人生的剧本——不是你父母的续集，不是你子女的前传，更不是你朋友的外篇。", author: "尼采", category: "自我人生", translation: "You must figure out the script of your own life—not a sequel to your parents, not a prequel to your children, nor a side story of your friends."),
        Quote(text: "那些杀不死你的，终将使你更强大。", author: "尼采", category: "磨难与成长", translation: "What does not kill me makes me stronger."),
        Quote(text: "一个人知道自己为什么而活，就可以忍受任何一种生活。", author: "尼采", category: "目标与坚韧", translation: "He who has a why to live for can bear almost any how."),
        Quote(text: "每一个不曾起舞的日子，都是对生命的辜负。", author: "尼采", category: "生命与珍惜", translation: "Every day spent without dancing is a betrayal of life."),
        Quote(text: "生活不是等待风暴过去，而是学会在雨中翩翩起舞。", author: "维维安·格林", category: "心态与乐观"),
        Quote(text: "你的时间有限，不要浪费在重复别人的生活上。", author: "史蒂夫·乔布斯", category: "时间与人生", translation: "Your time is limited, so don't waste it living someone else's life."),
        Quote(text: "保持饥饿，保持愚蠢。", author: "史蒂夫·乔布斯", category: "求知与谦逊", translation: "Stay hungry, stay foolish."),
        Quote(text: "创新就是把各种事物整合在一起。", author: "史蒂夫·乔布斯", category: "创新与创造", translation: "Innovation is putting things together."),
        Quote(text: "成就一番伟业的唯一途径就是热爱自己的事业。", author: "史蒂夫·乔布斯", category: "热爱与事业", translation: "The only way to do great work is to love what you do."),
        Quote(text: "不要被教条所限，不要活在别人的观念里。", author: "史蒂夫·乔布斯", category: "独立思考", translation: "Don't be trapped by dogma, don't live in someone else's thinking."),
        Quote(text: "我思故我在。", author: "笛卡尔", category: "思考与存在"),
        Quote(text: "读一本好书，就是和许多高尚的人谈话。", author: "歌德", category: "读书与学习", translation: "Reading a good book is like talking with many noble people."),
        Quote(text: "谁若游戏人生，他就一事无成；谁不能主宰自己，便永远是一个奴隶。", author: "歌德", category: "人生态度", translation: "He who plays with life achieves nothing; he who cannot master himself will always be a slave."),
        Quote(text: "你若要喜爱你自己的价值，你就得给世界创造价值。", author: "歌德", category: "价值与创造", translation: "If you want to enjoy your own value, you must create value for the world."),
        Quote(text: "没有比人生更艰难的艺术了，因为其他的艺术或学问，到处都有教师。", author: "塞涅卡", category: "人生艺术"),
        Quote(text: "生命如同寓言，其价值不在长短，而在内容。", author: "塞涅卡", category: "生命价值"),
        Quote(text: "真正的人生，只有在经过艰难卓绝的斗争之后才能实现。", author: "塞涅卡", category: "奋斗与人生")
    ]
    
    private static let quotes_2: [Quote] = [
        Quote(text: "人生就像骑自行车，要保持平衡就得不断前进。", author: "爱因斯坦", category: "人生与前进", translation: "Life is like riding a bicycle. To keep your balance, you must keep moving."),
        Quote(text: "天才是百分之一的灵感加百分之九十九的汗水。", author: "爱迪生", category: "勤奋与天才", translation: "Genius is one percent inspiration and ninety-nine percent perspiration."),
        Quote(text: "失败也是我需要的，它和成功对我一样有价值。", author: "爱迪生", category: "失败与成功", translation: "Failure is also what I need. It is as valuable to me as success."),
        Quote(text: "我们最大的弱点在于放弃。成功的必然之路就是不断的重来一次。", author: "爱迪生", category: "坚持与成功", translation: "Our greatest weakness lies in giving up. The surest way to succeed is to try just one more time."),
        Quote(text: "生活中的许多失败，是因为人们在放弃的时候没有认识到，他们距离成功只有一步之遥。", author: "爱迪生", category: "坚持与成功", translation: "Many of life's failures are people who did not realize how close they were to success when they gave up."),
        Quote(text: "不要只因一次失败，就放弃你原来决心想达到的目的。", author: "莎士比亚", category: "坚持与目标", translation: "Do not, for one repulse, give up the purpose that you resolved to achieve."),
        Quote(text: "黑夜无论怎样悠长，白昼总会到来。", author: "莎士比亚", category: "希望与信念", translation: "No matter how long the night, the dawn will come."),
        Quote(text: "明智的人决不坐下来为失败而哀号，他们一定乐观地寻找办法来加以挽救。", author: "莎士比亚", category: "乐观与行动", translation: "Wise men never sit and wail over failure; they optimistically look for ways to fix it."),
        Quote(text: "本来无望的事，大胆尝试，往往能成功。", author: "莎士比亚", category: "尝试与成功", translation: "Things that seem hopeless can often succeed with bold attempts."),
        Quote(text: "希望是坚韧的拐杖，忍耐是旅行袋，携带它们，人可以登上永恒之旅。", author: "罗素", category: "希望与忍耐"),
        Quote(text: "伟大的事业是根源于坚韧不断的工作，以全副精神去从事，不避艰苦。", author: "罗素", category: "事业与坚韧"),
        Quote(text: "人的真实生活不在于穿衣吃饭，而在于科学和思想。", author: "雨果", category: "精神与思想", translation: "Real life is not about food and clothing, but about science and thought."),
        Quote(text: "世界上最宽阔的是海洋，比海洋更宽阔的是天空，比天空更宽阔的是人的心灵。", author: "雨果", category: "胸怀与心灵", translation: "The widest thing in the world is the ocean; wider than the ocean is the sky; wider than the sky is the human heart."),
        Quote(text: "所谓活着的人，就是不断挑战的人，不断攀登命运险峰的人。", author: "雨果", category: "挑战与人生", translation: "Those who are truly alive are those who keep challenging, keep climbing the dangerous peaks of fate."),
        Quote(text: "人生下来不是为了拖着锁链，而是为了展开双翼。", author: "雨果", category: "自由与成长", translation: "Man is born not to drag chains, but to spread his wings."),
        Quote(text: "艺术的大道上荆棘丛生，这也是好事，常人望而却步，只有意志坚强的人例外。", author: "雨果", category: "意志与艺术", translation: "The path of art is full of thorns, which is also a good thing. Common people shrink back; only the strong-willed are exceptions."),
        Quote(text: "人生是一场无休、无歇、无情的战斗，凡是要做个够得上称为人的人，都得时时向无形的敌人作战。", author: "罗曼·罗兰", category: "人生与战斗", translation: "Life is an endless, restless, and ruthless battle. Anyone who wants to be a true man must fight invisible enemies at all times."),
        Quote(text: "最可怕的敌人，就是没有坚强的信念。", author: "罗曼·罗兰", category: "信念与敌人", translation: "The most terrible enemy is the lack of strong faith."),
        Quote(text: "世界上只有一种真正的英雄主义，那就是在认清生活的真相后依然热爱生活。", author: "罗曼·罗兰", category: "英雄主义", translation: "There is only one true heroism in the world: to see the world as it is, and to love it."),
        Quote(text: "一个人的价值，应该看他贡献什么，而不应当看他取得什么。", author: "爱因斯坦", category: "价值与贡献", translation: "The value of a man should be seen in what he gives, not in what he is able to receive."),
        Quote(text: "对真理和知识的追求并为之奋斗，是人的最高品质之一。", author: "爱因斯坦", category: "真理与追求", translation: "The pursuit of truth and knowledge is one of the highest qualities of man."),
        Quote(text: "成功=艰苦的劳动+正确的方法+少说空话。", author: "爱因斯坦", category: "成功公式", translation: "Success = hard work + right method + less empty talk."),
        Quote(text: "凡在小事上对真理持轻率态度的人，在大事上也是不足信的。", author: "爱因斯坦", category: "真理与态度", translation: "Anyone who is careless with truth in small matters cannot be trusted in important matters."),
        Quote(text: "人生的价值，即以其人对于当代所做的工作为尺度。", author: "徐玮", category: "人生价值"),
        Quote(text: "一个没有受到献身的热情所鼓舞的人，永远不会做出什么伟大的事情来。", author: "车尔尼雪夫斯基", category: "热情与伟大"),
        Quote(text: "人的活动如果没有理想的鼓舞，就会变得空虚而渺小。", author: "车尔尼雪夫斯基", category: "理想与人生"),
        Quote(text: "把语言化为行动，比把行动化为语言困难得多。", author: "高尔基", category: "行动与语言"),
        Quote(text: "只有满怀自信的人，才能在任何地方都怀有自信地沉浸在生活中，并实现自己的意志。", author: "高尔基", category: "自信与意志"),
        Quote(text: "书籍是人类进步的阶梯。", author: "高尔基", category: "读书与进步"),
        Quote(text: "我扑在书籍上，像饥饿的人扑在面包上一样。", author: "高尔基", category: "读书与渴望"),
        Quote(text: "天才出于勤奋。", author: "高尔基", category: "勤奋与天才"),
        Quote(text: "时间最不偏私，给任何人都是二十四小时；时间也是偏私，给任何人都不是二十四小时。", author: "赫胥黎", category: "时间与公平"),
        Quote(text: "充满着欢乐与斗争精神的人们，永远带着欢乐，欢迎雷霆与阳光。", author: "赫胥黎", category: "乐观与斗争"),
        Quote(text: "过去属于死神，未来属于你自己。", author: "雪莱", category: "过去与未来"),
        Quote(text: "如果冬天来了，春天还会远吗？", author: "雪莱", category: "希望与信念"),
        Quote(text: "辛勤的蜜蜂永没有时间的悲哀。", author: "布莱克", category: "勤劳与悲伤"),
        Quote(text: "成功的秘诀，在永不改变既定的目的。", author: "卢梭", category: "成功与目标"),
        Quote(text: "人生的价值是由自己决定的。", author: "卢梭", category: "人生价值"),
        Quote(text: "忍耐是苦涩的，但它的果实是甜蜜的。", author: "卢梭", category: "忍耐与收获"),
        Quote(text: "你想成为幸福的人吗？但愿你首先学会吃得起苦。", author: "屠格涅夫", category: "幸福与苦难"),
        Quote(text: "先相信你自己，然后别人才会相信你。", author: "屠格涅夫", category: "自信与信任"),
        Quote(text: "不会宽容别人的人，是不配受到别人宽容的。", author: "屠格涅夫", category: "宽容与待人"),
        Quote(text: "奋斗是万物之父。", author: "陶行知", category: "奋斗与创造"),
        Quote(text: "千教万教教人求真，千学万学学做真人。", author: "陶行知", category: "教育与求真"),
        Quote(text: "行动是老子，知识是儿子，创造是孙子。", author: "陶行知", category: "行动与创造"),
        Quote(text: "滴自己的汗，吃自己的饭，自己的事自己干，靠人靠天靠祖上，不算是好汉。", author: "陶行知", category: "自立与奋斗"),
        Quote(text: "捧着一颗心来，不带半根草去。", author: "陶行知", category: "奉献与教育"),
        Quote(text: "为中华之崛起而读书。", author: "周恩来", category: "志向与爱国"),
        Quote(text: "畏惧错误就是毁灭进步。", author: "怀特黑德", category: "错误与进步"),
        Quote(text: "当你的希望一个个落空，你也要坚定，要沉着！", author: "朗费罗", category: "希望与坚定"),
        Quote(text: "成功的花，人们只惊羡她现时的明艳！然而当初她的芽儿，浸透了奋斗的泪泉，洒遍了牺牲的血雨。", author: "冰心", category: "成功与奋斗"),
        Quote(text: "生命从八十岁开始。", author: "冰心", category: "生命与开始"),
        Quote(text: "有了爱就有了一切。", author: "冰心", category: "爱与人生"),
        Quote(text: "读书好，好读书，读好书。", author: "冰心", category: "读书与学习"),
        Quote(text: "青年人，珍重的描写罢，时间正翻着书页，请你着笔！", author: "冰心", category: "青春与珍惜"),
        Quote(text: "真理，哪怕只见到一线，我们也不能让它的光辉变得暗淡。", author: "李四光", category: "真理与追求"),
        Quote(text: "我是炎黄子孙，理所当然地要把学到的知识全部奉献给我亲爱的祖国。", author: "李四光", category: "爱国与奉献"),
        Quote(text: "一个能思想的人，才真是一个力量无边的人。", author: "巴尔扎克", category: "思想与力量", translation: "A person who can think is truly a person of boundless power."),
        Quote(text: "苦难是人生的老师。", author: "巴尔扎克", category: "苦难与成长", translation: "Suffering is the teacher of life."),
        Quote(text: "人类所有的力量，只是耐心加上时间的混合。", author: "巴尔扎克", category: "力量与耐心", translation: "All human power is a mixture of patience and time."),
        Quote(text: "持续不断的劳动是人生的铁律，也是艺术的铁律。", author: "巴尔扎克", category: "劳动与人生", translation: "Continuous labor is the iron law of life, and also of art."),
        Quote(text: "没有伟大的愿望，就没有伟大的天才。", author: "巴尔扎克", category: "愿望与天才", translation: "Without great desires, there is no great genius."),
        Quote(text: "一个人只要强烈地坚持不懈地追求，他就能达到目的。", author: "司汤达", category: "追求与目标"),
        Quote(text: "如果一个人不知道他要驶向哪个码头，那么任何风都不会是顺风。", author: "塞涅卡", category: "目标与方向"),
        Quote(text: "只要持续地努力，不懈地奋斗，就没有征服不了的东西。", author: "塞涅卡", category: "努力与征服"),
        Quote(text: "服从真理，就能征服一切事物。", author: "塞涅卡", category: "真理与征服"),
        Quote(text: "幸福的人都一样，不幸的人各有各的不幸。", author: "列夫·托尔斯泰", category: "幸福与不幸", translation: "Happy families are all alike; every unhappy family is unhappy in its own way."),
        Quote(text: "人生不是一种享乐，而是一桩十分沉重的工作。", author: "列夫·托尔斯泰", category: "人生与工作", translation: "Life is not a pleasure, but a very heavy task."),
        Quote(text: "你必须在额上流汗，以资获得你的面包。", author: "列夫·托尔斯泰", category: "劳动与收获", translation: "You must sweat on your brow to earn your bread."),
        Quote(text: "被人爱和爱别人是同样的幸福，而且一旦得到它，就够受用一辈子。", author: "列夫·托尔斯泰", category: "爱与幸福", translation: "To be loved and to love are the same happiness, and once obtained, it is enough for a lifetime."),
        Quote(text: "理想的书籍是智慧的钥匙。", author: "列夫·托尔斯泰", category: "书籍与智慧", translation: "Ideal books are the keys to wisdom."),
        Quote(text: "心灵纯洁的人，生活充满甜蜜和喜悦。", author: "列夫·托尔斯泰", category: "心灵与生活", translation: "Pure-hearted people live a life full of sweetness and joy."),
        Quote(text: "做好事的乐趣乃是人生唯一可靠的幸福。", author: "列夫·托尔斯泰", category: "善良与幸福", translation: "The joy of doing good is the only reliable happiness in life."),
        Quote(text: "人生并非游戏，因此我们没有权利随意放弃它。", author: "列夫·托尔斯泰", category: "人生与责任", translation: "Life is not a game, so we have no right to give it up at will."),
        Quote(text: "环境愈艰难困苦，就愈需要坚定毅力和信心，而且，懈怠的害处也愈大。", author: "列夫·托尔斯泰", category: "困境与毅力", translation: "The harder the circumstances, the more we need firm perseverance and faith, and the greater the harm of laziness."),
        Quote(text: "人生的一切变化，一切魅力，一切美都是由光明和阴影构成的。", author: "列夫·托尔斯泰", category: "人生与变化", translation: "All changes, all charms, and all beauties of life are made of light and shadow."),
        Quote(text: "你热爱生命吗？那么别浪费时间，因为时间是组成生命的材料。", author: "富兰克林", category: "生命与时间", translation: "Do you love life? Then do not waste time, for time is the stuff life is made of."),
        Quote(text: "诚实和勤勉，应该成为你永久的伴侣。", author: "富兰克林", category: "品格与人生", translation: "Honesty and diligence should be your permanent companions."),
        Quote(text: "失足，你可以马上恢复站立；失信，你也许永难挽回。", author: "富兰克林", category: "诚信与人生", translation: "If you slip, you can soon stand up again; if you break your word, you may never recover it."),
        Quote(text: "勤奋是好运之母。", author: "富兰克林", category: "勤奋与好运", translation: "Diligence is the mother of good luck."),
        Quote(text: "你要追求工作，别让工作追求你。", author: "富兰克林", category: "工作与主动", translation: "Drive your business, let not your business drive you."),
        Quote(text: "不惜牺牲自由以图苟安的人，既不配享受自由，也不配获得安全。", author: "富兰克林", category: "自由与安全", translation: "They that can give up essential liberty to obtain a little temporary safety deserve neither liberty nor safety."),
        Quote(text: "我从未见过一个早起、勤奋、谨慎、诚实的人抱怨命运不好。", author: "富兰克林", category: "勤奋与命运", translation: "I never saw an early-rising, diligent, prudent, and honest man complain of bad luck."),
        Quote(text: "懿行美德远胜于美貌。", author: "富兰克林", category: "美德与美貌", translation: "A good character is far better than a beautiful face."),
        Quote(text: "空袋子难以直立。", author: "富兰克林", category: "学识与自立", translation: "An empty bag cannot stand upright."),
        Quote(text: "敢于冲撞命运才是天才。", author: "雨果", category: "命运与天才", translation: "Genius is the one who dares to challenge fate."),
        Quote(text: "没有风暴，船帆不过是一块破布。", author: "雨果", category: "逆境与价值", translation: "Without a storm, a sail is nothing but a rag."),
        Quote(text: "最高的道德是什么？那就是爱国心。", author: "拿破仑", category: "道德与爱国"),
        Quote(text: "不想当将军的士兵不是好士兵。", author: "拿破仑", category: "志向与进取"),
        Quote(text: "人生的光荣，不在永不失败，而在于能够屡仆屡起。", author: "拿破仑", category: "失败与奋起"),
        Quote(text: "真正的才智是刚毅的志向。", author: "拿破仑", category: "才智与志向"),
        Quote(text: "在我的字典中，没有不可能的字眼。", author: "拿破仑", category: "可能与信念"),
        Quote(text: "凡是决心取得胜利的人是从来不说不可能的。", author: "拿破仑", category: "胜利与信念"),
        Quote(text: "天下兴亡，匹夫有责。", author: "顾炎武", category: "责任与爱国"),
        Quote(text: "君子之学，死而后已。", author: "顾炎武", category: "学习与坚持"),
        Quote(text: "丈夫志四海，万里犹比邻。", author: "曹植", category: "志向与胸怀"),
        Quote(text: "捐躯赴国难，视死忽如归。", author: "曹植", category: "爱国与牺牲"),
        Quote(text: "燕雀戏藩柴，安识鸿鹄游。", author: "曹植", category: "志向与见识"),
        Quote(text: "江山代有才人出，各领风骚数百年。", author: "赵翼", category: "人才与时代"),
        Quote(text: "满眼生机转化钧，天工人巧日争新。", author: "赵翼", category: "创新与发展"),
        Quote(text: "我不相信手掌的纹路，但我相信手掌加上手指的力量。", author: "毕淑敏", category: "命运与努力"),
        Quote(text: "人生是没有意义的，你要为之确立一个意义。", author: "毕淑敏", category: "人生意义"),
        Quote(text: "幸福是一种心灵的振颤。", author: "毕淑敏", category: "幸福与心灵"),
        Quote(text: "磨砺内心比油饰外表要难得多。", author: "毕淑敏", category: "内心与外表"),
        Quote(text: "有一颗大心，才盛得下喜怒，输得出力量。", author: "毕淑敏", category: "心灵与力量"),
        Quote(text: "成功并不等于快乐，快乐却等于成功。", author: "毕淑敏", category: "成功与快乐"),
        Quote(text: "人可以被毁灭，但不能被打败。", author: "海明威", category: "意志与失败", translation: "A man can be destroyed but not defeated.")
    ]
    
    private static let quotes_3: [Quote] = [
        Quote(text: "人生像攀登一座山，而找寻出路，却是一种学习的过程，我们应当在这过程中，学习稳定、冷静，学习如何从慌乱中找到生机。", author: "席慕蓉", category: "人生与学习"),
        Quote(text: "青春是一本太仓促的书。", author: "席慕蓉", category: "青春与珍惜"),
        Quote(text: "所有的结局都已写好，所有的泪水也都已启程，却忽然忘了是怎么样的一个开始。", author: "席慕蓉", category: "人生与开始"),
        Quote(text: "故乡的歌是一支清远的笛，总在有月亮的晚上响起。", author: "席慕蓉", category: "故乡与思念"),
        Quote(text: "人生如逆旅，我亦是行人。", author: "苏轼", category: "人生与旅途"),
        Quote(text: "莫听穿林打叶声，何妨吟啸且徐行。竹杖芒鞋轻胜马，谁怕？一蓑烟雨任平生。", author: "苏轼", category: "豁达与人生"),
        Quote(text: "回首向来萧瑟处，归去，也无风雨也无晴。", author: "苏轼", category: "淡定与人生"),
        Quote(text: "但愿人长久，千里共婵娟。", author: "苏轼", category: "思念与祝福"),
        Quote(text: "大江东去，浪淘尽，千古风流人物。", author: "苏轼", category: "历史与人生"),
        Quote(text: "会挽雕弓如满月，西北望，射天狼。", author: "苏轼", category: "志向与豪情"),
        Quote(text: "人生到处知何似，应似飞鸿踏雪泥。泥上偶然留指爪，鸿飞那复计东西。", author: "苏轼", category: "人生与漂泊"),
        Quote(text: "不识庐山真面目，只缘身在此山中。", author: "苏轼", category: "认知与局限"),
        Quote(text: "欲把西湖比西子，淡妆浓抹总相宜。", author: "苏轼", category: "审美与自然"),
        Quote(text: "宁可食无肉，不可居无竹。无肉令人瘦，无竹令人俗。", author: "苏轼", category: "品格与追求"),
        Quote(text: "发奋识遍天下字，立志读尽人间书。", author: "苏轼", category: "学习与志向"),
        Quote(text: "博观而约取，厚积而薄发。", author: "苏轼", category: "积累与发挥"),
        Quote(text: "腹有诗书气自华。", author: "苏轼", category: "学识与气质"),
        Quote(text: "忧劳可以兴国，逸豫可以亡身。", author: "欧阳修", category: "忧患与安乐"),
        Quote(text: "醉翁之意不在酒，在乎山水之间也。", author: "欧阳修", category: "情趣与山水"),
        Quote(text: "人生自是有情痴，此恨不关风与月。", author: "欧阳修", category: "情感与人生"),
        Quote(text: "月上柳梢头，人约黄昏后。", author: "欧阳修", category: "美好与浪漫"),
        Quote(text: "立身以立学为先，立学以读书为本。", author: "欧阳修", category: "学习与读书"),
        Quote(text: "君子之修身也，内正其心，外正其容。", author: "欧阳修", category: "修身与正心"),
        Quote(text: "不以物喜，不以己悲。", author: "范仲淹", category: "心态与境界"),
        Quote(text: "先天下之忧而忧，后天下之乐而乐。", author: "范仲淹", category: "胸怀与天下"),
        Quote(text: "云山苍苍，江水泱泱，先生之风，山高水长。", author: "范仲淹", category: "品格与风范"),
        Quote(text: "宁鸣而死，不默而生。", author: "范仲淹", category: "气节与人生"),
        Quote(text: "家贫志不移，贪读如饥渴。", author: "范仲淹", category: "志向与读书"),
        Quote(text: "有生必有死，早终非命促。", author: "陶渊明", category: "生死与坦然"),
        Quote(text: "采菊东篱下，悠然见南山。", author: "陶渊明", category: "闲适与自然"),
        Quote(text: "不戚戚于贫贱，不汲汲于富贵。", author: "陶渊明", category: "淡泊与名利"),
        Quote(text: "盛年不重来，一日难再晨。及时当勉励，岁月不待人。", author: "陶渊明", category: "时光与珍惜"),
        Quote(text: "好读书，不求甚解。每有会意，便欣然忘食。", author: "陶渊明", category: "读书与乐趣"),
        Quote(text: "悟已往之不谏，知来者之可追。实迷途其未远，觉今是而昨非。", author: "陶渊明", category: "觉悟与未来"),
        Quote(text: "刑天舞干戚，猛志固常在。", author: "陶渊明", category: "斗志与精神"),
        Quote(text: "落地为兄弟，何必骨肉亲。", author: "陶渊明", category: "情谊与博爱"),
        Quote(text: "衣食当须纪，力耕不吾欺。", author: "陶渊明", category: "劳动与收获"),
        Quote(text: "长太息以掩涕兮，哀民生之多艰。", author: "屈原", category: "忧国与忧民"),
        Quote(text: "亦余心之所善兮，虽九死其犹未悔。", author: "屈原", category: "追求与无悔"),
        Quote(text: "举世皆浊我独清，众人皆醉我独醒。", author: "屈原", category: "清醒与独立"),
        Quote(text: "与天地兮同寿，与日月兮齐光。", author: "屈原", category: "志向与永恒"),
        Quote(text: "吾不能变心而从俗兮，固将愁苦而终穷。", author: "屈原", category: "坚守与品格"),
        Quote(text: "乘骐骥以驰骋兮，来吾道夫先路。", author: "屈原", category: "引领与进取"),
        Quote(text: "春蚕到死丝方尽，蜡炬成灰泪始干。", author: "李商隐", category: "奉献与执着"),
        Quote(text: "身无彩凤双飞翼，心有灵犀一点通。", author: "李商隐", category: "心灵与默契"),
        Quote(text: "此情可待成追忆，只是当时已惘然。", author: "李商隐", category: "回忆与遗憾"),
        Quote(text: "何当共剪西窗烛，却话巴山夜雨时。", author: "李商隐", category: "思念与期待"),
        Quote(text: "夕阳无限好，只是近黄昏。", author: "李商隐", category: "美好与短暂"),
        Quote(text: "直道相思了无益，未妨惆怅是清狂。", author: "李商隐", category: "相思与执着"),
        Quote(text: "沉舟侧畔千帆过，病树前头万木春。", author: "刘禹锡", category: "希望与新生"),
        Quote(text: "山不在高，有仙则名。水不在深，有龙则灵。", author: "刘禹锡", category: "内涵与价值"),
        Quote(text: "自古逢秋悲寂寥，我言秋日胜春朝。晴空一鹤排云上，便引诗情到碧霄。", author: "刘禹锡", category: "乐观与豪情"),
        Quote(text: "东边日出西边雨，道是无晴却有晴。", author: "刘禹锡", category: "情感与微妙"),
        Quote(text: "千淘万漉虽辛苦，吹尽狂沙始到金。", author: "刘禹锡", category: "坚持与收获"),
        Quote(text: "莫道桑榆晚，为霞尚满天。", author: "刘禹锡", category: "暮年与乐观"),
        Quote(text: "芳林新叶催陈叶，流水前波让后波。", author: "刘禹锡", category: "发展与传承"),
        Quote(text: "试玉要烧三日满，辨材须待七年期。", author: "白居易", category: "识人与时间"),
        Quote(text: "野火烧不尽，春风吹又生。", author: "白居易", category: "顽强与生命力"),
        Quote(text: "天生我材必有用，千金散尽还复来。", author: "李白", category: "自信与人生"),
        Quote(text: "长风破浪会有时，直挂云帆济沧海。", author: "李白", category: "信念与前程"),
        Quote(text: "人生得意须尽欢，莫使金樽空对月。", author: "李白", category: "人生与珍惜"),
        Quote(text: "抽刀断水水更流，举杯消愁愁更愁。", author: "李白", category: "愁绪与无奈"),
        Quote(text: "君不见黄河之水天上来，奔流到海不复回。君不见高堂明镜悲白发，朝如青丝暮成雪。", author: "李白", category: "时光与人生"),
        Quote(text: "安能摧眉折腰事权贵，使我不得开心颜。", author: "李白", category: "骨气与自由"),
        Quote(text: "飞流直下三千尺，疑是银河落九天。", author: "李白", category: "壮景与想象"),
        Quote(text: "桃花潭水深千尺，不及汪伦送我情。", author: "李白", category: "友情与深厚"),
        Quote(text: "孤帆远影碧空尽，唯见长江天际流。", author: "李白", category: "送别与思念"),
        Quote(text: "举杯邀明月，对影成三人。", author: "李白", category: "孤独与浪漫"),
        Quote(text: "蜀道之难，难于上青天。", author: "李白", category: "艰难与挑战"),
        Quote(text: "仰天大笑出门去，我辈岂是蓬蒿人。", author: "李白", category: "自信与豪情"),
        Quote(text: "国破山河在，城春草木深。感时花溅泪，恨别鸟惊心。", author: "杜甫", category: "忧国与伤时"),
        Quote(text: "会当凌绝顶，一览众山小。", author: "杜甫", category: "志向与攀登"),
        Quote(text: "读书破万卷，下笔如有神。", author: "杜甫", category: "读书与写作"),
        Quote(text: "朱门酒肉臭，路有冻死骨。", author: "杜甫", category: "社会与不公"),
        Quote(text: "安得广厦千万间，大庇天下寒士俱欢颜，风雨不动安如山。", author: "杜甫", category: "胸怀与理想"),
        Quote(text: "出师未捷身先死，长使英雄泪满襟。", author: "杜甫", category: "遗憾与敬仰"),
        Quote(text: "随风潜入夜，润物细无声。", author: "杜甫", category: "奉献与无声"),
        Quote(text: "白日放歌须纵酒，青春作伴好还乡。", author: "杜甫", category: "喜悦与归乡"),
        Quote(text: "烽火连三月，家书抵万金。", author: "杜甫", category: "战乱与亲情"),
        Quote(text: "正是江南好风景，落花时节又逢君。", author: "杜甫", category: "重逢与感慨"),
        Quote(text: "露从今夜白，月是故乡明。", author: "杜甫", category: "思乡与明月"),
        Quote(text: "文章千古事，得失寸心知。", author: "杜甫", category: "创作与心得"),
        Quote(text: "为人性僻耽佳句，语不惊人死不休。", author: "杜甫", category: "创作与执着"),
        Quote(text: "海内存知己，天涯若比邻。", author: "王勃", category: "友情与距离"),
        Quote(text: "落霞与孤鹜齐飞，秋水共长天一色。", author: "王勃", category: "美景与意境"),
        Quote(text: "老当益壮，宁移白首之心？穷且益坚，不坠青云之志。", author: "王勃", category: "壮志与坚持"),
        Quote(text: "关山难越，谁悲失路之人；萍水相逢，尽是他乡之客。", author: "王勃", category: "人生与漂泊"),
        Quote(text: "时运不齐，命途多舛。冯唐易老，李广难封。", author: "王勃", category: "命运与遗憾"),
        Quote(text: "醉里挑灯看剑，梦回吹角连营。八百里分麾下炙，五十弦翻塞外声，沙场秋点兵。", author: "辛弃疾", category: "壮志与豪情"),
        Quote(text: "众里寻他千百度，蓦然回首，那人却在，灯火阑珊处。", author: "辛弃疾", category: "追寻与发现"),
        Quote(text: "了却君王天下事，赢得生前身后名。可怜白发生！", author: "辛弃疾", category: "壮志与遗憾"),
        Quote(text: "凭谁问：廉颇老矣，尚能饭否？", author: "辛弃疾", category: "壮志与暮年"),
        Quote(text: "青山遮不住，毕竟东流去。", author: "辛弃疾", category: "趋势与必然"),
        Quote(text: "少年不识愁滋味，爱上层楼。爱上层楼，为赋新词强说愁。", author: "辛弃疾", category: "成长与愁绪"),
        Quote(text: "而今识尽愁滋味，欲说还休。欲说还休，却道天凉好个秋。", author: "辛弃疾", category: "沧桑与淡定"),
        Quote(text: "想当年，金戈铁马，气吞万里如虎。", author: "辛弃疾", category: "壮志与豪情"),
        Quote(text: "千古兴亡多少事？悠悠。不尽长江滚滚流。", author: "辛弃疾", category: "历史与感慨"),
        Quote(text: "我见青山多妩媚，料青山见我应如是。", author: "辛弃疾", category: "自然与知音"),
        Quote(text: "不恨古人吾不见，恨古人不见吾狂耳。", author: "辛弃疾", category: "狂放与自信"),
        Quote(text: "生当作人杰，死亦为鬼雄。至今思项羽，不肯过江东。", author: "李清照", category: "气节与豪情"),
        Quote(text: "寻寻觅觅，冷冷清清，凄凄惨惨戚戚。", author: "李清照", category: "愁绪与孤寂"),
        Quote(text: "这次第，怎一个愁字了得！", author: "李清照", category: "愁绪与深重"),
        Quote(text: "莫道不销魂，帘卷西风，人比黄花瘦。", author: "李清照", category: "思念与憔悴"),
        Quote(text: "知否知否，应是绿肥红瘦。", author: "李清照", category: "春逝与感慨"),
        Quote(text: "花自飘零水自流，一种相思，两处闲愁。", author: "李清照", category: "相思与闲愁"),
        Quote(text: "此情无计可消除，才下眉头，却上心头。", author: "李清照", category: "相思与深情"),
        Quote(text: "物是人非事事休，欲语泪先流。", author: "李清照", category: "沧桑与悲伤"),
        Quote(text: "只恐双溪舴艋舟，载不动许多愁。", author: "李清照", category: "愁绪与沉重"),
        Quote(text: "九万里风鹏正举。风休住，蓬舟吹取三山去！", author: "李清照", category: "壮志与豪情"),
        Quote(text: "见客入来，袜刬金钗溜。和羞走，倚门回首，却把青梅嗅。", author: "李清照", category: "少女与娇羞"),
        Quote(text: "常记溪亭日暮，沉醉不知归路。兴尽晚回舟，误入藕花深处。", author: "李清照", category: "回忆与美好"),
        Quote(text: "争渡，争渡，惊起一滩鸥鹭。", author: "李清照", category: "趣味与生机"),
        Quote(text: "无可奈何花落去，似曾相识燕归来。", author: "晏殊", category: "时光与感慨"),
        Quote(text: "昨夜西风凋碧树，独上高楼，望尽天涯路。", author: "晏殊", category: "思念与远方"),
        Quote(text: "欲寄彩笺兼尺素，山长水阔知何处。", author: "晏殊", category: "思念与无奈"),
        Quote(text: "绿杨烟外晓寒轻，红杏枝头春意闹。", author: "宋祁", category: "春景与生机"),
        Quote(text: "浮生长恨欢娱少，肯爱千金轻一笑。", author: "宋祁", category: "人生与欢乐"),
        Quote(text: "为君持酒劝斜阳，且向花间留晚照。", author: "宋祁", category: "惜时与美好"),
        Quote(text: "寒蝉凄切，对长亭晚，骤雨初歇。", author: "柳永", category: "离别与凄凉"),
        Quote(text: "执手相看泪眼，竟无语凝噎。", author: "柳永", category: "离别与深情"),
        Quote(text: "念去去，千里烟波，暮霭沉沉楚天阔。", author: "柳永", category: "离别与远方"),
        Quote(text: "多情自古伤离别，更那堪，冷落清秋节！", author: "柳永", category: "离别与愁绪"),
        Quote(text: "今宵酒醒何处？杨柳岸，晓风残月。", author: "柳永", category: "离别与孤寂"),
        Quote(text: "此去经年，应是良辰好景虚设。便纵有千种风情，更与何人说？", author: "柳永", category: "离别与寂寞"),
        Quote(text: "衣带渐宽终不悔，为伊消得人憔悴。", author: "柳永", category: "相思与执着"),
        Quote(text: "才子词人，自是白衣卿相。", author: "柳永", category: "自信与才情"),
        Quote(text: "忍把浮名，换了浅斟低唱。", author: "柳永", category: "淡泊与才情"),
        Quote(text: "问君能有几多愁？恰似一江春水向东流。", author: "李煜", category: "愁绪与深沉"),
        Quote(text: "春花秋月何时了？往事知多少。", author: "李煜", category: "往事与感慨"),
        Quote(text: "小楼昨夜又东风，故国不堪回首月明中。", author: "李煜", category: "亡国与思乡"),
        Quote(text: "雕栏玉砌应犹在，只是朱颜改。", author: "李煜", category: "物是人非"),
        Quote(text: "无言独上西楼，月如钩。寂寞梧桐深院锁清秋。", author: "李煜", category: "孤寂与凄凉"),
        Quote(text: "剪不断，理还乱，是离愁。别是一般滋味在心头。", author: "李煜", category: "离愁与滋味"),
        Quote(text: "林花谢了春红，太匆匆。无奈朝来寒雨晚来风。", author: "李煜", category: "春逝与无奈"),
        Quote(text: "胭脂泪，相留醉，几时重。自是人生长恨水长东。", author: "李煜", category: "人生长恨"),
        Quote(text: "梦里不知身是客，一晌贪欢。", author: "李煜", category: "梦境与现实"),
        Quote(text: "独自莫凭栏，无限江山，别时容易见时难。", author: "李煜", category: "江山与离别"),
        Quote(text: "流水落花春去也，天上人间。", author: "李煜", category: "春逝与感慨"),
        Quote(text: "多少恨，昨夜梦魂中。还似旧时游上苑，车如流水马如龙。花月正春风。", author: "李煜", category: "故国与回忆"),
        Quote(text: "闲梦远，南国正芳春。船上管弦江面渌，满城飞絮辊轻尘。忙杀看花人！", author: "李煜", category: "南国与春景"),
        Quote(text: "闲梦远，南国正清秋。千里江山寒色远，芦花深处泊孤舟。笛在月明楼。", author: "李煜", category: "南国与秋景"),
        Quote(text: "塞下秋来风景异，衡阳雁去无留意。", author: "范仲淹", category: "边塞与秋景"),
        Quote(text: "四面边声连角起，千嶂里，长烟落日孤城闭。", author: "范仲淹", category: "边塞与壮阔"),
        Quote(text: "浊酒一杯家万里，燕然未勒归无计。", author: "范仲淹", category: "思乡与报国"),
        Quote(text: "羌管悠悠霜满地，人不寐，将军白发征夫泪。", author: "范仲淹", category: "思乡与艰辛"),
        Quote(text: "碧云天，黄叶地，秋色连波，波上寒烟翠。", author: "范仲淹", category: "秋景与意境"),
        Quote(text: "山映斜阳天接水，芳草无情，更在斜阳外。", author: "范仲淹", category: "景色与情思"),
        Quote(text: "黯乡魂，追旅思，夜夜除非，好梦留人睡。", author: "范仲淹", category: "思乡与难眠"),
        Quote(text: "明月楼高休独倚，酒入愁肠，化作相思泪。", author: "范仲淹", category: "相思与愁绪"),
        Quote(text: "江上往来人，但爱鲈鱼美。君看一叶舟，出没风波里。", author: "范仲淹", category: "民生与艰辛"),
        Quote(text: "业精于勤，荒于嬉；行成于思，毁于随。", author: "韩愈", category: "勤奋与思考"),
        Quote(text: "师者，所以传道受业解惑也。", author: "韩愈", category: "教育与师道"),
        Quote(text: "闻道有先后，术业有专攻。", author: "韩愈", category: "学习与专长"),
        Quote(text: "书山有路勤为径，学海无涯苦作舟。", author: "韩愈", category: "学习与勤奋"),
        Quote(text: "千里马常有，而伯乐不常有。", author: "韩愈", category: "人才与机遇"),
        Quote(text: "世有伯乐，然后有千里马。", author: "韩愈", category: "人才与发现"),
        Quote(text: "大凡物不得其平则鸣。", author: "韩愈", category: "表达与不平"),
        Quote(text: "文以载道。", author: "周敦颐", category: "文章与思想"),
        Quote(text: "出淤泥而不染，濯清涟而不妖。", author: "周敦颐", category: "品格与高洁"),
        Quote(text: "中通外直，不蔓不枝，香远益清，亭亭净植。", author: "周敦颐", category: "品格与正直"),
        Quote(text: "删繁就简三秋树，领异标新二月花。", author: "郑板桥", category: "创新与简洁"),
        Quote(text: "虚心竹有低头叶，傲骨梅无仰面花。", author: "郑板桥", category: "谦逊与傲骨"),
        Quote(text: "海到无边天作岸，山登绝顶我为峰。", author: "林则徐", category: "志向与豪情"),
        Quote(text: "岂能尽如人意，但求无愧我心。", author: "刘伯温", category: "心态与坦然"),
        Quote(text: "金玉其外，败絮其中。", author: "刘基", category: "表象与实质"),
        Quote(text: "一年之计莫如树谷，十年之计莫如树木，终身之计莫如树人。", author: "管子", category: "教育与长远"),
        Quote(text: "仓廪实而知礼节，衣食足而知荣辱。", author: "管子", category: "物质与精神"),
        Quote(text: "不积跬步，无以至千里；不积小流，无以成江海。", author: "荀子", category: "积累与坚持"),
        Quote(text: "锲而舍之，朽木不折；锲而不舍，金石可镂。", author: "荀子", category: "坚持与毅力"),
        Quote(text: "青，取之于蓝，而青于蓝。", author: "荀子", category: "学习与超越"),
        Quote(text: "君子博学而日参省乎己，则知明而行无过矣。", author: "荀子", category: "学习与自省"),
        Quote(text: "蓬生麻中，不扶而直；白沙在涅，与之俱黑。", author: "荀子", category: "环境与影响"),
        Quote(text: "不闻不若闻之，闻之不若见之，见之不若知之，知之不若行之。", author: "荀子", category: "认知与实践"),
        Quote(text: "天行有常，不为尧存，不为桀亡。", author: "荀子", category: "规律与客观"),
        Quote(text: "先义而后利者荣，先利而后义者辱。", author: "荀子", category: "义利与荣辱")
    ]
    
    private static let quotes_4: [Quote] = [
        Quote(text: "五岭逶迤腾细浪，乌蒙磅礴走泥丸。", author: "毛泽东", category: "壮志与豪情"),
        Quote(text: "金沙水拍云崖暖，大渡桥横铁索寒。", author: "毛泽东", category: "长征与艰险"),
        Quote(text: "更喜岷山千里雪，三军过后尽开颜。", author: "毛泽东", category: "胜利与喜悦"),
        Quote(text: "俱往矣，数风流人物，还看今朝。", author: "毛泽东", category: "英雄与时代"),
        Quote(text: "雄关漫道真如铁，而今迈步从头越。", author: "毛泽东", category: "坚定与前进"),
        Quote(text: "从头越，苍山如海，残阳如血。", author: "毛泽东", category: "壮阔与悲壮"),
        Quote(text: "不到长城非好汉，屈指行程二万。", author: "毛泽东", category: "壮志与毅力"),
        Quote(text: "世上无难事，只要肯登攀。", author: "毛泽东", category: "坚持与信心"),
        Quote(text: "自信人生二百年，会当水击三千里。", author: "毛泽东", category: "自信与豪情"),
        Quote(text: "星星之火，可以燎原。", author: "毛泽东", category: "希望与力量"),
        Quote(text: "虚心使人进步，骄傲使人落后。", author: "毛泽东", category: "谦逊与进步"),
        Quote(text: "好好学习，天天向上。", author: "毛泽东", category: "学习与进步"),
        Quote(text: "自己动手，丰衣足食。", author: "毛泽东", category: "自力更生"),
        Quote(text: "没有调查，就没有发言权。", author: "毛泽东", category: "实践与认知"),
        Quote(text: "前途是光明的，道路是曲折的。", author: "毛泽东", category: "前途与道路"),
        Quote(text: "一万年太久，只争朝夕。", author: "毛泽东", category: "时间与紧迫"),
        Quote(text: "宜将剩勇追穷寇，不可沽名学霸王。", author: "毛泽东", category: "胜利与进取"),
        Quote(text: "天若有情天亦老，人间正道是沧桑。", author: "毛泽东", category: "正道与沧桑"),
        Quote(text: "人民，只有人民，才是创造世界历史的动力。", author: "毛泽东", category: "人民与历史"),
        Quote(text: "一滴水只有放进大海里才永远不会干涸，一个人只有当他把自己和集体事业融合在一起的时候才能最有力量。", author: "雷锋", category: "集体与力量"),
        Quote(text: "人的生命是有限的，可是，为人民服务是无限的，我要把有限的生命，投入到无限的为人民服务之中去。", author: "雷锋", category: "奉献与人生"),
        Quote(text: "青春啊，永远是美好的，可是真正的青春，只属于这些永远力争上游的人，永远忘我劳动的人，永远谦虚的人。", author: "雷锋", category: "青春与奋斗"),
        Quote(text: "对待同志要像春天般的温暖，对待工作要像夏天一样火热，对待个人主义要像秋风扫落叶一样，对待敌人要像严冬一样残酷无情。", author: "雷锋", category: "态度与原则"),
        Quote(text: "如果你是一滴水，你是否滋润了一寸土地？如果你是一线阳光，你是否照亮了一分黑暗？如果你是一颗粮食，你是否哺育了有用的生命？", author: "雷锋", category: "价值与奉献"),
        Quote(text: "我愿永远做一个螺丝钉。", author: "雷锋", category: "平凡与伟大"),
        Quote(text: "钉子有两个长处：一个是挤劲，一个是钻劲。我们在学习上也要提倡这种钉子精神，善于挤和善于钻。", author: "雷锋", category: "学习与精神"),
        Quote(text: "吃饭是为了活着，但活着不是为了吃饭。", author: "雷锋", category: "人生与意义"),
        Quote(text: "不经风雨，长不成大树；不受百炼，难以成钢。", author: "雷锋", category: "磨砺与成长"),
        Quote(text: "把别人的困难当成自己的困难，把同志的愉快看成自己的幸福。", author: "雷锋", category: "助人与幸福"),
        Quote(text: "骄傲的人，其实是无知的人。他不知道自己能吃几碗干饭，他不懂得自己只是沧海一粟。", author: "雷锋", category: "骄傲与无知"),
        Quote(text: "力量从团结来，智慧从劳动来，行动从思想来，荣誉从集体来。", author: "雷锋", category: "团结与智慧"),
        Quote(text: "我是广大劳苦大众当中的一员，我能帮助人民克服一点困难，是最幸福的。", author: "雷锋", category: "幸福与奉献"),
        Quote(text: "我们比较容易承认行为上的错误、过失和缺点，而对于思想上的错误、过失和缺点则不然。", author: "歌德", category: "反省与思想", translation: "We more easily admit errors in conduct than errors in thought."),
        Quote(text: "我们的生活就像旅行，思想是导游者，没有导游者，一切都会停止。目标会丧失，力量也会化为乌有。", author: "歌德", category: "思想与人生", translation: "Life is like a journey, and thought is the guide. Without a guide, everything stops. Goals are lost, and strength turns to nothing."),
        Quote(text: "伟大的需要使人崇高，卑微的需要使人沉沦。", author: "歌德", category: "需要与品格", translation: "Great needs make a man noble; small needs make him sink."),
        Quote(text: "在今天和明天之间，有一段很长的时间；趁你还有精神的时候，学习迅速地办事。", author: "歌德", category: "时间与行动", translation: "Between today and tomorrow, there is a long time. While you still have energy, learn to act quickly."),
        Quote(text: "一个有真正大才能的人却在工作过程中感到最高度的快乐。", author: "歌德", category: "才能与快乐", translation: "A truly talented person feels the highest joy while working."),
        Quote(text: "智慧只能在真理中发现。", author: "歌德", category: "智慧与真理", translation: "Wisdom can only be found in truth."),
        Quote(text: "你若要为你的意义而欢喜，就必须给这个世界以意义。", author: "歌德", category: "意义与创造", translation: "If you want to rejoice in your own meaning, you must give meaning to the world."),
        Quote(text: "想象力比知识更重要，因为知识是有限的，而想象力概括着世界上的一切，推动着进步，并且是知识进化的源泉。", author: "爱因斯坦", category: "想象与知识", translation: "Imagination is more important than knowledge. For knowledge is limited, whereas imagination embraces the entire world, stimulating progress, and giving birth to evolution."),
        Quote(text: "世间最美好的东西，莫过于有几个头脑和心地都很正直的严正的朋友。", author: "爱因斯坦", category: "友谊与正直", translation: "The best thing in the world is to have a few true friends with upright minds and hearts."),
        Quote(text: "在真理和认识方面，任何以权威者自居的人，必将在上帝的戏笑中垮台！", author: "爱因斯坦", category: "真理与权威", translation: "In the realm of truth and knowledge, anyone who acts as an authority will collapse under God's laughter!"),
        Quote(text: "没有侥幸这回事，最偶然的意外，似乎也都是有必然性的。", author: "爱因斯坦", category: "偶然与必然", translation: "There is no such thing as luck. The most accidental events seem to have necessity."),
        Quote(text: "我绝对相信，在这个世界上，财富绝不能使人类进步。", author: "爱因斯坦", category: "财富与进步", translation: "I am absolutely convinced that no wealth in the world can help humanity progress."),
        Quote(text: "学习知识要善于思考，思考，再思考，我就是靠这个方法成为科学家的。", author: "爱因斯坦", category: "学习与思考", translation: "Learn to think, think, and think again. That is how I became a scientist."),
        Quote(text: "行一件好事，心中泰然；行一件歹事，衾影抱愧。", author: "神涵光", category: "行善与心安"),
        Quote(text: "一个人最伤心的事情无过于良心的死灭。", author: "郭沫若", category: "良心与道德"),
        Quote(text: "土扶可城墙，积德为厚地。", author: "李白", category: "积德与厚重"),
        Quote(text: "人生内无贤父兄，外无严师友，而能有成者少矣。", author: "吕公著", category: "成长与师友"),
        Quote(text: "应该热心地致力于照道德行事，而不要空谈道德。", author: "德谟克利特", category: "道德与行动", translation: "We should earnestly strive to act morally, rather than merely talk about morality."),
        Quote(text: "感情有着极大的鼓舞力量，因此，它是一切道德行为的重要前提。", author: "凯洛夫", category: "感情与道德", translation: "Emotion has great inspiring power, so it is an important basis of all moral behavior."),
        Quote(text: "没有伟大的品格，就没有伟大的人，甚至也没有伟大的艺术家，伟大的行动者。", author: "罗曼·罗兰", category: "品格与伟大", translation: "Without great character, there are no great men, no great artists, and no great men of action."),
        Quote(text: "人类被赋予了一种工作，那就是精神的成长。", author: "列夫·托尔斯泰", category: "精神与成长", translation: "Man is given a task: the growth of the spirit."),
        Quote(text: "人在智慧上应当是明豁的，道德上应该是清白的，身体上应该是清洁的。", author: "契诃夫", category: "人的品质", translation: "A man should be clear in mind, pure in morals, and clean in body."),
        Quote(text: "良心是由人的知识和全部生活方式来决定的。", author: "马克思", category: "良心与认知", translation: "Conscience is determined by man's knowledge and his whole way of life."),
        Quote(text: "守法和有良心的人，即使有迫切的需要也不会偷窃，可是，即使把百万金元给了盗贼，也没法儿指望他从此不偷不盗。", author: "克雷洛夫", category: "品德与本性", translation: "A law-abiding man with a conscience will not steal even in great need, but a thief will not stop stealing even if given a million gold coins."),
        Quote(text: "精神上的道德力量发挥了它的潜能，举起了它的旗帜，于是我们的爱国热情和正义感在现实中均得施展其威力和作用。", author: "黑格尔", category: "道德与力量", translation: "When moral power shows its potential and raises its flag, our patriotism and sense of justice can show their strength and effect in reality."),
        Quote(text: "勿以恶小而为之，勿以善小而不为。惟贤惟德，能服于人。", author: "刘备", category: "善恶与德行"),
        Quote(text: "不患位之不尊，而患德之不崇；不耻禄之不伙，而耻智之不博。", author: "张衡", category: "德行与学识"),
        Quote(text: "害羞是畏惧或害怕羞辱的情绪，这种情绪可以阻止人不去犯某些卑鄙的行为。", author: "斯宾诺莎", category: "羞耻与道德", translation: "Shyness is the fear of being humiliated. This feeling can stop people from doing some base actions."),
        Quote(text: "少壮不努力，老大徒伤悲。", author: "汉乐府", category: "努力与后悔"),
        Quote(text: "黑发不知勤学早，白发方悔读书迟。", author: "颜真卿", category: "勤学与后悔"),
        Quote(text: "问渠那得清如许，为有源头活水来。", author: "朱熹", category: "读书与源头"),
        Quote(text: "古人学问无遗力，少壮工夫老始成。", author: "陆游", category: "学习与坚持"),
        Quote(text: "旧书不厌百回读，熟读深思子自知。", author: "苏轼", category: "读书与深思"),
        Quote(text: "为学之实，固在践履。", author: "朱熹", category: "学习与实践"),
        Quote(text: "读书有三到，谓心到，眼到，口到。", author: "朱熹", category: "读书方法"),
        Quote(text: "朝闻道，夕死可矣。", author: "孔子", category: "真理与追求"),
        Quote(text: "士志于道，而耻恶衣恶食者，未足与议也。", author: "孔子", category: "志向与物欲"),
        Quote(text: "见贤思齐焉，见不贤而内自省也。", author: "孔子", category: "学习与自省"),
        Quote(text: "君子欲讷于言而敏于行。", author: "孔子", category: "言行与谨慎"),
        Quote(text: "德不孤，必有邻。", author: "孔子", category: "品德与朋友"),
        Quote(text: "质胜文则野，文胜质则史。文质彬彬，然后君子。", author: "孔子", category: "修养与文质"),
        Quote(text: "知者乐水，仁者乐山；知者动，仁者静；知者乐，仁者寿。", author: "孔子", category: "智慧与仁德"),
        Quote(text: "默而识之，学而不厌，诲人不倦。", author: "孔子", category: "学习与教导"),
        Quote(text: "志于道，据于德，依于仁，游于艺。", author: "孔子", category: "志向与修养"),
        Quote(text: "饭疏食饮水，曲肱而枕之，乐亦在其中矣。不义而富且贵，于我如浮云。", author: "孔子", category: "安贫与乐道"),
        Quote(text: "其为人也，发愤忘食，乐以忘忧，不知老之将至云尔。", author: "孔子", category: "好学与快乐"),
        Quote(text: "我非生而知之者，好古，敏以求之者也。", author: "孔子", category: "学习与追求"),
        Quote(text: "鸟之将死，其鸣也哀；人之将死，其言也善。", author: "孔子", category: "临终与善言"),
        Quote(text: "士不可以不弘毅，任重而道远。仁以为己任，不亦重乎？死而后已，不亦远乎？", author: "孔子", category: "士志与任重"),
        Quote(text: "大人者，不失其赤子之心者也。", author: "孟子", category: "品格与初心"),
        Quote(text: "君子以仁存心，以礼存心。仁者爱人，有礼者敬人。", author: "孟子", category: "仁爱与礼敬"),
        Quote(text: "爱人者，人恒爱之；敬人者，人恒敬之。", author: "孟子", category: "仁爱与互敬"),
        Quote(text: "孝子之至，莫大乎尊亲。", author: "孟子", category: "孝道与尊亲"),
        Quote(text: "人人亲其亲，长其长，而天下平。", author: "孟子", category: "伦理与天下"),
        Quote(text: "父子有亲，君臣有义，夫妇有别，长幼有序，朋友有信。", author: "孟子", category: "人伦与道义"),
        Quote(text: "有恒产者有恒心，无恒产者无恒心。", author: "孟子", category: "财产与道德"),
        Quote(text: "民事不可缓也。", author: "孟子", category: "民生与重要"),
        Quote(text: "乐民之乐者，民亦乐其乐；忧民之忧者，民亦忧其忧。", author: "孟子", category: "君主与民生"),
        Quote(text: "乐以天下，忧以天下，然而不王者，未之有也。", author: "孟子", category: "天下与王道"),
        Quote(text: "君仁，莫不仁；君义，莫不义；君正，莫不正。", author: "孟子", category: "君主与垂范"),
        Quote(text: "一正君而国定矣。", author: "孟子", category: "君主与国家"),
        Quote(text: "惟仁者宜在高位。不仁而在高位，是播其恶于众也。", author: "孟子", category: "仁政与高位"),
        Quote(text: "上有好者，下必有甚焉者矣。", author: "孟子", category: "上行下效"),
        Quote(text: "夫人必自侮，然后人侮之；家必自毁，而后人毁之；国必自伐，而后人伐之。", author: "孟子", category: "自取灭亡"),
        Quote(text: "天作孽，犹可违；自作孽，不可活。", author: "孟子", category: "祸福与自招"),
        Quote(text: "祸福无不自己求之者。", author: "孟子", category: "祸福与自招"),
        Quote(text: "心之官则思，思则得之，不思则不得也。", author: "孟子", category: "思考与获得"),
        Quote(text: "先立乎其大者，则其小者不能夺也。", author: "孟子", category: "根本与枝节"),
        Quote(text: "从其大体为大人，从其小体为小人。", author: "孟子", category: "君子与小人"),
        Quote(text: "人之所以异于禽兽者几希，庶民去之，君子存之。", author: "孟子", category: "人与禽兽"),
        Quote(text: "万物皆备于我矣。反身而诚，乐莫大焉。强恕而行，求仁莫近焉。", author: "孟子", category: "自我与仁道"),
        Quote(text: "尽其心者，知其性也。知其性，则知天矣。", author: "孟子", category: "心性与天道"),
        Quote(text: "存其心，养其性，所以事天也。", author: "孟子", category: "存心养性"),
        Quote(text: "夭寿不贰，修身以俟之，所以立命也。", author: "孟子", category: "修身立命"),
        Quote(text: "莫非命也，顺受其正。是故知命者不立乎岩墙之下。", author: "孟子", category: "命运与顺应"),
        Quote(text: "尽其道而死者，正命也；桎梏死者，非正命也。", author: "孟子", category: "命运与正道"),
        Quote(text: "求则得之，舍则失之，是求有益于得也，求在我者也。", author: "孟子", category: "追求与自我"),
        Quote(text: "求之有道，得之有命，是求无益于得也，求在外者也。", author: "孟子", category: "追求与命运"),
        Quote(text: "穷不失义，达不离道。", author: "孟子", category: "道义与穷达"),
        Quote(text: "古之人，得志，泽加于民；不得志，修身见于世。穷则独善其身，达则兼善天下。", author: "孟子", category: "人生与境界"),
        Quote(text: "待文王而后兴者，凡民也。若夫豪杰之士，虽无文王犹兴。", author: "孟子", category: "豪杰与奋发"),
        Quote(text: "以佚道使民，虽劳不怨。以生道杀民，虽死不怨杀者。", author: "孟子", category: "治民与道义"),
        Quote(text: "杀之而不怨，利之而不庸，民日迁善而不知为之者。", author: "孟子", category: "治民与化育"),
        Quote(text: "夫君子所过者化，所存者神，上下与天地同流，岂曰小补之哉？", author: "孟子", category: "君子与化育"),
        Quote(text: "仁言不如仁声之入人深也，善政不如善教之得民也。", author: "孟子", category: "教化与政治"),
        Quote(text: "善政，民畏之；善教，民爱之。善政得民财，善教得民心。", author: "孟子", category: "政治与教化"),
        Quote(text: "人之所不学而能者，其良能也；所不虑而知者，其良知也。", author: "孟子", category: "良知良能"),
        Quote(text: "孩提之童无不知爱其亲者，及其长也，无不知敬其兄也。", author: "孟子", category: "良知与天性"),
        Quote(text: "亲亲，仁也；敬长，义也；无他，达之天下也。", author: "孟子", category: "仁义与天下"),
        Quote(text: "知者无不知也，当务之为急；仁者无不爱也，急亲贤之为务。", author: "孟子", category: "知仁与务急"),
        Quote(text: "尧舜之知而不遍物，急先务也；尧舜之仁不遍爱人，急亲贤也。", author: "孟子", category: "尧舜与务急"),
        Quote(text: "食而弗爱，豕交之也；爱而不敬，兽畜之也。", author: "孟子", category: "爱敬与待人"),
        Quote(text: "恭敬者，币之未将者也。恭敬而无实，君子不可虚拘。", author: "孟子", category: "恭敬与实质"),
        Quote(text: "君子之所以教者五：有如时雨化之者，有成德者，有达财者，有答问者，有私淑艾者。", author: "孟子", category: "教育方法"),
        Quote(text: "道在迩而求诸远，事在易而求诸难：人人亲其亲，长其长，而天下平。", author: "孟子", category: "道与平易"),
        Quote(text: "无为其所不为，无欲其所不欲，如此而已矣。", author: "孟子", category: "修身与本分"),
        Quote(text: "人之有德慧术知者，恒存乎疢疾。", author: "孟子", category: "磨难与智慧"),
        Quote(text: "独孤臣孽子，其操心也危，其虑患也深，故达。", author: "孟子", category: "困境与通达"),
        Quote(text: "言近而指远者，善言也；守约而施博者，善道也。", author: "孟子", category: "善言善道"),
        Quote(text: "君子之言也，不下带而道存焉；君子之守，修其身而天下平。", author: "孟子", category: "君子言道修身"),
        Quote(text: "人病舍其田而芸人之田——所求于人者重，而所以自任者轻。", author: "孟子", category: "苛人恕己"),
        Quote(text: "尧舜，性者也；汤武，反之也。", author: "孟子", category: "圣贤与本性"),
        Quote(text: "动容周旋中礼者，盛德之至也。", author: "孟子", category: "礼仪与盛德"),
        Quote(text: "哭死而哀，非为生者也。经德不回，非以干禄也。言语必信，非以正行也。", author: "孟子", category: "德行与本真"),
        Quote(text: "君子行法，以俟命而已矣。", author: "孟子", category: "君子行法俟命"),
        Quote(text: "广土众民，君子欲之，所乐不存焉。中天下而立，定四海之民，君子乐之，所性不存焉。", author: "孟子", category: "君子所乐所性"),
        Quote(text: "君子所性，虽大行不加焉，虽穷居不损焉，分定故也。", author: "孟子", category: "君子本性"),
        Quote(text: "君子所性，仁义礼智根于心，其生色也睟然，见于面，盎于背，施于四体，四体不言而喻。", author: "孟子", category: "君子本性与德容"),
        Quote(text: "天下有善养老，则仁人以为己归矣。", author: "孟子", category: "养老与仁人"),
        Quote(text: "易其田畴，薄其税敛，民可使富也。", author: "孟子", category: "富民之政"),
        Quote(text: "食之以时，用之以礼，财不可胜用也。", author: "孟子", category: "用财与礼义"),
        Quote(text: "圣人治天下，使有菽粟如水火。菽粟如水火，而民焉有不仁者乎？", author: "孟子", category: "富民与仁道"),
        Quote(text: "仁之胜不仁也，犹水胜火。今之为仁者，犹以一杯水救一车薪之火也；不熄，则谓之水不胜火，此又与于不仁之甚者也，亦终必亡而已矣。", author: "孟子", category: "仁与不仁"),
        Quote(text: "五谷者，种之美者也；苟为不熟，不如荑稗。夫仁，亦在乎熟之而已矣。", author: "孟子", category: "仁与成熟"),
        Quote(text: "羿之教人射，必志于彀；学者亦必志于彀。大匠诲人必以规矩，学者亦必以规矩。", author: "孟子", category: "学习与规矩"),
        Quote(text: "天时不如地利，地利不如人和。", author: "孟子", category: "成功与人和"),
        Quote(text: "三里之城，七里之郭，环而攻之而不胜。夫环而攻之，必有得天时者矣；然而不胜者，是天时不如地利也。", author: "孟子", category: "天时不如地利"),
        Quote(text: "城非不高也，池非不深也，兵革非不坚利也，米粟非不多也；委而去之，是地利不如人和也。", author: "孟子", category: "地利不如人和"),
        Quote(text: "故曰：域民不以封疆之界，固国不以山溪之险，威天下不以兵革之利。", author: "孟子", category: "治国与人和"),
        Quote(text: "得道者多助，失道者寡助。寡助之至，亲戚畔之；多助之至，天下顺之。", author: "孟子", category: "道义与人心"),
        Quote(text: "以天下之所顺，攻亲戚之所畔；故君子有不战，战必胜矣。", author: "孟子", category: "仁者无敌"),
        Quote(text: "君子所以异于人者，以其存心也。君子以仁存心，以礼存心。", author: "孟子", category: "君子存心"),
        Quote(text: "仁者爱人，有礼者敬人。爱人者，人恒爱之；敬人者，人恒敬之。", author: "孟子", category: "仁爱与互敬"),
        Quote(text: "有人于此，其待我以横逆，则君子必自反也：我必不仁也，必无礼也，此物奚宜至哉？", author: "孟子", category: "君子自反"),
        Quote(text: "其自反而仁矣，自反而有礼矣，其横逆由是也，君子必自反也：我必不忠。", author: "孟子", category: "君子自反"),
        Quote(text: "自反而忠矣，其横逆由是也，君子曰：此亦妄人也已矣。如此，则与禽兽奚择哉？于禽兽又何难焉？", author: "孟子", category: "君子待妄人"),
        Quote(text: "是故君子有终身之忧，无一朝之患也。乃若所忧则有之：舜，人也；我，亦人也。舜为法于天下，可传于后世，我由未免为乡人也，是则可忧也。", author: "孟子", category: "君子之忧"),
        Quote(text: "忧之如何？如舜而已矣。若夫君子所患则亡矣。非仁无为也，非礼无行也。如有一朝之患，则君子不患矣。", author: "孟子", category: "君子行仁"),
        Quote(text: "禹、稷当平世，三过其门而不入，孔子贤之。", author: "孟子", category: "禹稷公而忘私"),
        Quote(text: "颜子当乱世，居于陋巷，一箪食，一瓢饮；人不堪其忧，颜子不改其乐，孔子贤之。", author: "孟子", category: "颜子安贫乐道"),
        Quote(text: "禹、稷、颜回同道。禹思天下有溺者，由己溺之也；稷思天下有饥者，由己饥之也，是以如是其急也。", author: "孟子", category: "禹稷忧民"),
        Quote(text: "禹、稷、颜子易地则皆然。", author: "孟子", category: "圣贤同道"),
        Quote(text: "顺天者昌，逆天者亡。", author: "孟子", category: "顺天逆天"),
        Quote(text: "天视自我民视，天听自我民听。", author: "孟子", category: "天视天听"),
        Quote(text: "天降下民，作之君，作之师。", author: "孟子", category: "天降下民"),
        Quote(text: "天之生此民也，使先知觉后知，使先觉觉后觉也。", author: "孟子", category: "先知觉后知"),
        Quote(text: "予，天民之先觉者也；予将以斯道觉斯民也。非予觉之，而谁也？", author: "孟子", category: "孟子自任"),
        Quote(text: "思天下之民匹夫匹妇有不被尧舜之泽者，若己推而内之沟中。其自任以天下之重如此。", author: "孟子", category: "自任天下之重"),
        Quote(text: "天下有道，以道殉身；天下无道，以身殉道。未闻以道殉乎人者也。", author: "孟子", category: "道与身"),
        Quote(text: "天下之生久矣，一治一乱。", author: "孟子", category: "天下治乱"),
        Quote(text: "世衰道微，邪说暴行有作，臣弑其君者有之，子弑其父者有之。", author: "孟子", category: "世衰道微"),
        Quote(text: "孔子惧，作《春秋》。《春秋》，天子之事也；是故孔子曰：知我者其惟《春秋》乎！罪我者其惟《春秋》乎！", author: "孟子", category: "孔子作春秋"),
        Quote(text: "圣王不作，诸侯放恣，处士横议，杨朱、墨翟之言盈天下。", author: "孟子", category: "处士横议"),
        Quote(text: "天下之言，不归杨，则归墨。杨氏为我，是无君也；墨氏兼爱，是无父也。无父无君，是禽兽也。", author: "孟子", category: "杨墨无父无君"),
        Quote(text: "杨墨之道不息，孔子之道不著，是邪说诬民，充塞仁义也。", author: "孟子", category: "杨墨息孔子道"),
        Quote(text: "仁义充塞，则率兽食人，人将相食。", author: "孟子", category: "仁义充塞"),
        Quote(text: "吾为此惧，闲先圣之道，距杨墨，放淫辞，邪说者不得作。", author: "孟子", category: "距杨墨"),
        Quote(text: "作于其心，害于其事；作于其事，害于其政。圣人复起，不易吾言矣。", author: "孟子", category: "邪说害政"),
        Quote(text: "昔者禹抑洪水而天下平，周公兼夷狄、驱猛兽而百姓宁，孔子成《春秋》而乱臣贼子惧。", author: "孟子", category: "三圣之功"),
        Quote(text: "我亦欲正人心，息邪说，距诐行，放淫辞，以承三圣者；岂好辩哉？予不得已也。", author: "孟子", category: "孟子好辩"),
        Quote(text: "能言距杨墨者，圣人之徒也。", author: "孟子", category: "距杨墨为圣人徒"),
        Quote(text: "尽信书，则不如无书。", author: "孟子", category: "尽信书不如无书")
    ]
    
    private static let quotes_5: [Quote] = [
        Quote(text: "富贵不能淫，贫贱不能移，威武不能屈，此之谓大丈夫。", author: "孟子", category: "气节与品格"),
        Quote(text: "老吾老，以及人之老；幼吾幼，以及人之幼。", author: "孟子", category: "仁爱与博爱"),
        Quote(text: "民为贵，社稷次之，君为轻。", author: "孟子", category: "民本与治国"),
        Quote(text: "鱼，我所欲也；熊掌，亦我所欲也。二者不可得兼，舍鱼而取熊掌者也。", author: "孟子", category: "选择与取舍"),
        Quote(text: "生，亦我所欲也；义，亦我所欲也。二者不可得兼，舍生而取义者也。", author: "孟子", category: "生死与道义"),
        Quote(text: "故天将降大任于斯人也，必先苦其心志，劳其筋骨，饿其体肤，空乏其身，行拂乱其所为，所以动心忍性，曾益其所不能。", author: "孟子", category: "磨难与成长"),
        Quote(text: "人恒过，然后能改；困于心，衡于虑，而后作；征于色，发于声，而后喻。", author: "孟子", category: "过错与成长"),
        Quote(text: "入则无法家拂士，出则无敌国外患者，国恒亡。然后知生于忧患而死于安乐也。", author: "孟子", category: "忧患与安乐"),
        Quote(text: "知之为知之，不知为不知，是知也。", author: "孔子", category: "学习与诚实"),
        Quote(text: "三人行，必有我师焉。", author: "孔子", category: "学习与谦逊"),
        Quote(text: "学而时习之，不亦说乎？", author: "孔子", category: "学习与快乐"),
        Quote(text: "温故而知新，可以为师矣。", author: "孔子", category: "学习与复习"),
        Quote(text: "学而不思则罔，思而不学则殆。", author: "孔子", category: "学习与思考"),
        Quote(text: "敏而好学，不耻下问。", author: "孔子", category: "学习与谦逊"),
        Quote(text: "默而识之，学而不厌，诲人不倦。", author: "孔子", category: "学习与教导"),
        Quote(text: "知之者不如好之者，好之者不如乐之者。", author: "孔子", category: "学习与兴趣"),
        Quote(text: "见贤思齐焉，见不贤而内自省也。", author: "孔子", category: "学习与自省"),
        Quote(text: "君子坦荡荡，小人长戚戚。", author: "孔子", category: "品格与心态"),
        Quote(text: "己所不欲，勿施于人。", author: "孔子", category: "待人与恕道"),
        Quote(text: "仁者不忧，知者不惑，勇者不惧。", author: "孔子", category: "品格与智慧"),
        Quote(text: "三军可夺帅也，匹夫不可夺志也。", author: "孔子", category: "志向与骨气"),
        Quote(text: "岁寒，然后知松柏之后凋也。", author: "孔子", category: "坚韧与品格"),
        Quote(text: "逝者如斯夫，不舍昼夜。", author: "孔子", category: "时光与珍惜"),
        Quote(text: "工欲善其事，必先利其器。", author: "孔子", category: "准备与效率"),
        Quote(text: "人无远虑，必有近忧。", author: "孔子", category: "远见与规划"),
        Quote(text: "欲速则不达，见小利则大事不成。", author: "孔子", category: "速度与大局"),
        Quote(text: "君子和而不同，小人同而不和。", author: "孔子", category: "处世与原则"),
        Quote(text: "君子泰而不骄，小人骄而不泰。", author: "孔子", category: "品格与态度"),
        Quote(text: "朝闻道，夕死可矣。", author: "孔子", category: "真理与追求"),
        Quote(text: "士不可以不弘毅，任重而道远。", author: "孔子", category: "士志与任重"),
        Quote(text: "德不孤，必有邻。", author: "孔子", category: "品德与朋友"),
        Quote(text: "质胜文则野，文胜质则史。文质彬彬，然后君子。", author: "孔子", category: "修养与文质"),
        Quote(text: "知者乐水，仁者乐山。", author: "孔子", category: "智慧与仁德"),
        Quote(text: "不义而富且贵，于我如浮云。", author: "孔子", category: "不义富且贵如浮云"),
        Quote(text: "发愤忘食，乐以忘忧，不知老之将至。", author: "孔子", category: "发愤忘食乐以忘忧"),
        Quote(text: "有教无类。", author: "孔子", category: "有教无类"),
        Quote(text: "因材施教。", author: "孔子", category: "因材施教"),
        Quote(text: "不愤不启，不悱不发。", author: "孔子", category: "不愤不启不悱不发"),
        Quote(text: "举一隅不以三隅反，则不复也。", author: "孔子", category: "举一反三"),
        Quote(text: "道不同，不相为谋。", author: "孔子", category: "道不同不相为谋"),
        Quote(text: "父母在，不远游，游必有方。", author: "孔子", category: "父母在不远游"),
        Quote(text: "君子喻于义，小人喻于利。", author: "孔子", category: "君子喻于义小人喻于利"),
        Quote(text: "其身正，不令而行；其身不正，虽令不从。", author: "孔子", category: "其身正不令而行"),
        Quote(text: "苟正其身矣，于从政乎何有？不能正其身，如正人何？", author: "孔子", category: "正其身"),
        Quote(text: "近者说，远者来。", author: "孔子", category: "近者说远者来"),
        Quote(text: "既来之，则安之。", author: "孔子", category: "既来之则安之"),
        Quote(text: "吾恐季孙之忧，不在颛臾，而在萧墙之内也。", author: "孔子", category: "祸起萧墙"),
        Quote(text: "不患寡而患不均，不患贫而患不安。", author: "孔子", category: "患寡患不均"),
        Quote(text: "均无贫，和无寡，安无倾。", author: "孔子", category: "均无贫和无寡"),
        Quote(text: "上善若水。水善利万物而不争，处众人之所恶，故几于道。", author: "老子", category: "品格与道"),
        Quote(text: "千里之行，始于足下。", author: "老子", category: "行动与开始"),
        Quote(text: "合抱之木，生于毫末；九层之台，起于累土；千里之行，始于足下。", author: "老子", category: "积累与开始"),
        Quote(text: "知人者智，自知者明。胜人者有力，自胜者强。", author: "老子", category: "智慧与自知"),
        Quote(text: "知足者富，强行者有志。", author: "老子", category: "知足与志向"),
        Quote(text: "夫唯不争，故天下莫能与之争。", author: "老子", category: "处世与不争"),
        Quote(text: "祸兮福之所倚，福兮祸之所伏。", author: "老子", category: "祸福与辩证"),
        Quote(text: "大方无隅，大器晚成，大音希声，大象无形。", author: "老子", category: "境界与积累"),
        Quote(text: "道生一，一生二，二生三，三生万物。", author: "老子", category: "宇宙与道"),
        Quote(text: "人法地，地法天，天法道，道法自然。", author: "老子", category: "自然与道"),
        Quote(text: "治大国，若烹小鲜。", author: "老子", category: "治国与智慧"),
        Quote(text: "轻诺必寡信，多易必多难。", author: "老子", category: "诚信与难易"),
        Quote(text: "慎终如始，则无败事。", author: "老子", category: "坚持与谨慎"),
        Quote(text: "知不知，上；不知知，病。", author: "老子", category: "认知与谦逊"),
        Quote(text: "天网恢恢，疏而不失。", author: "老子", category: "规律与必然"),
        Quote(text: "信言不美，美言不信。善者不辩，辩者不善。知者不博，博者不知。", author: "老子", category: "真实与表象"),
        Quote(text: "既以为人己愈有，既以与人己愈多。", author: "老子", category: "给予与收获"),
        Quote(text: "天之道，利而不害；圣人之道，为而不争。", author: "老子", category: "天道与圣人"),
        Quote(text: "路漫漫其修远兮，吾将上下而求索。", author: "屈原", category: "探索与追求"),
        Quote(text: "长太息以掩涕兮，哀民生之多艰。", author: "屈原", category: "忧国与忧民"),
        Quote(text: "亦余心之所善兮，虽九死其犹未悔。", author: "屈原", category: "追求与无悔"),
        Quote(text: "举世皆浊我独清，众人皆醉我独醒。", author: "屈原", category: "清醒与独立"),
        Quote(text: "与天地兮同寿，与日月兮齐光。", author: "屈原", category: "志向与永恒"),
        Quote(text: "吾不能变心而从俗兮，固将愁苦而终穷。", author: "屈原", category: "坚守与品格"),
        Quote(text: "乘骐骥以驰骋兮，来吾道夫先路。", author: "屈原", category: "引领与进取"),
        Quote(text: "老骥伏枥，志在千里；烈士暮年，壮心不已。", author: "曹操", category: "志向与坚持"),
        Quote(text: "对酒当歌，人生几何？譬如朝露，去日苦多。", author: "曹操", category: "人生与时光"),
        Quote(text: "山不厌高，海不厌深。周公吐哺，天下归心。", author: "曹操", category: "求贤与天下"),
        Quote(text: "东临碣石，以观沧海。水何澹澹，山岛竦峙。", author: "曹操", category: "壮景与胸怀"),
        Quote(text: "树木丛生，百草丰茂。秋风萧瑟，洪波涌起。", author: "曹操", category: "秋景与壮阔"),
        Quote(text: "日月之行，若出其中；星汉灿烂，若出其里。", author: "曹操", category: "宇宙与胸怀"),
        Quote(text: "神龟虽寿，犹有竟时；腾蛇乘雾，终为土灰。", author: "曹操", category: "生命与有限"),
        Quote(text: "盈缩之期，不但在天；养怡之福，可得永年。", author: "曹操", category: "寿命与修养"),
        Quote(text: "幸甚至哉，歌以咏志。", author: "曹操", category: "抒怀与言志"),
        Quote(text: "本是同根生，相煎何太急。", author: "曹植", category: "兄弟与相残"),
        Quote(text: "煮豆燃豆萁，豆在釜中泣。", author: "曹植", category: "兄弟与相残"),
        Quote(text: "丈夫志四海，万里犹比邻。", author: "曹植", category: "志向与胸怀"),
        Quote(text: "捐躯赴国难，视死忽如归。", author: "曹植", category: "爱国与牺牲"),
        Quote(text: "燕雀戏藩柴，安识鸿鹄游。", author: "曹植", category: "志向与见识"),
        Quote(text: "国仇亮不塞，甘心思丧元。", author: "曹植", category: "爱国与勇气"),
        Quote(text: "烈士多悲心，小人偷自闲。", author: "曹植", category: "志士与庸人"),
        Quote(text: "高树多悲风，海水扬其波。利剑不在掌，结友何须多？", author: "曹植", category: "悲风与友情"),
        Quote(text: "不见篱下菊，重阳空自好。", author: "陶渊明", category: "重阳与菊花"),
        Quote(text: "采菊东篱下，悠然见南山。", author: "陶渊明", category: "闲适与自然"),
        Quote(text: "山气日夕佳，飞鸟相与还。", author: "陶渊明", category: "山景与归鸟"),
        Quote(text: "此中有真意，欲辨已忘言。", author: "陶渊明", category: "真意与忘言"),
        Quote(text: "结庐在人境，而无车马喧。", author: "陶渊明", category: "隐逸与宁静"),
        Quote(text: "问君何能尔？心远地自偏。", author: "陶渊明", category: "心远与宁静"),
        Quote(text: "种豆南山下，草盛豆苗稀。", author: "陶渊明", category: "田园与劳作"),
        Quote(text: "晨兴理荒秽，带月荷锄归。", author: "陶渊明", category: "劳作与月光"),
        Quote(text: "道狭草木长，夕露沾我衣。", author: "陶渊明", category: "田园与艰辛"),
        Quote(text: "衣沾不足惜，但使愿无违。", author: "陶渊明", category: "心愿与坚持"),
        Quote(text: "归去来兮，田园将芜胡不归？", author: "陶渊明", category: "归隐与田园"),
        Quote(text: "悟已往之不谏，知来者之可追。", author: "陶渊明", category: "觉悟与未来"),
        Quote(text: "实迷途其未远，觉今是而昨非。", author: "陶渊明", category: "迷途与觉悟"),
        Quote(text: "舟遥遥以轻飏，风飘飘而吹衣。", author: "陶渊明", category: "归程与轻快"),
        Quote(text: "问征夫以前路，恨晨光之熹微。", author: "陶渊明", category: "归心与晨光"),
        Quote(text: "乃瞻衡宇，载欣载奔。", author: "陶渊明", category: "归家与喜悦"),
        Quote(text: "三径就荒，松菊犹存。", author: "陶渊明", category: "家园与松菊"),
        Quote(text: "携幼入室，有酒盈樽。", author: "陶渊明", category: "家与酒"),
        Quote(text: "引壶觞以自酌，眄庭柯以怡颜。", author: "陶渊明", category: "自酌与怡然"),
        Quote(text: "倚南窗以寄傲，审容膝之易安。", author: "陶渊明", category: "傲世与安适"),
        Quote(text: "园日涉以成趣，门虽设而常关。", author: "陶渊明", category: "园趣与闭关"),
        Quote(text: "策扶老以流憩，时矫首而遐观。", author: "陶渊明", category: "悠游与远望"),
        Quote(text: "云无心以出岫，鸟倦飞而知还。", author: "陶渊明", category: "云鸟与归意"),
        Quote(text: "景翳翳以将入，抚孤松而盘桓。", author: "陶渊明", category: "暮色与孤松"),
        Quote(text: "归去来兮，请息交以绝游。", author: "陶渊明", category: "归隐与绝交"),
        Quote(text: "世与我而相违，复驾言兮焉求？", author: "陶渊明", category: "世违与无求"),
        Quote(text: "悦亲戚之情话，乐琴书以消忧。", author: "陶渊明", category: "亲情与琴书"),
        Quote(text: "农人告余以春及，将有事于西畴。", author: "陶渊明", category: "春事与农耕"),
        Quote(text: "或命巾车，或棹孤舟。", author: "陶渊明", category: "出游与舟车"),
        Quote(text: "既窈窕以寻壑，亦崎岖而经丘。", author: "陶渊明", category: "寻壑与经丘"),
        Quote(text: "木欣欣以向荣，泉涓涓而始流。", author: "陶渊明", category: "生机与泉流"),
        Quote(text: "善万物之得时，感吾生之行休。", author: "陶渊明", category: "万物与吾生"),
        Quote(text: "已矣乎！寓形宇内复几时？", author: "陶渊明", category: "人生与短暂"),
        Quote(text: "曷不委心任去留？胡为乎遑遑欲何之？", author: "陶渊明", category: "委心与去留"),
        Quote(text: "富贵非吾愿，帝乡不可期。", author: "陶渊明", category: "富贵与仙乡"),
        Quote(text: "怀良辰以孤往，或植杖而耘耔。", author: "陶渊明", category: "良辰与劳作"),
        Quote(text: "登东皋以舒啸，临清流而赋诗。", author: "陶渊明", category: "舒啸与赋诗"),
        Quote(text: "聊乘化以归尽，乐夫天命复奚疑！", author: "陶渊明", category: "乘化与乐天"),
        Quote(text: "盛年不重来，一日难再晨。", author: "陶渊明", category: "时光与珍惜"),
        Quote(text: "及时当勉励，岁月不待人。", author: "陶渊明", category: "勉励与岁月"),
        Quote(text: "不戚戚于贫贱，不汲汲于富贵。", author: "陶渊明", category: "淡泊与名利"),
        Quote(text: "好读书，不求甚解。每有会意，便欣然忘食。", author: "陶渊明", category: "读书与乐趣"),
        Quote(text: "闲静少言，不慕荣利。", author: "陶渊明", category: "闲静与淡泊"),
        Quote(text: "环堵萧然，不蔽风日；短褐穿结，箪瓢屡空，晏如也。", author: "陶渊明", category: "清贫与安然"),
        Quote(text: "常著文章自娱，颇示己志。", author: "陶渊明", category: "著文与言志"),
        Quote(text: "忘怀得失，以此自终。", author: "陶渊明", category: "忘怀与自终"),
        Quote(text: "黔娄之妻有言：不戚戚于贫贱，不汲汲于富贵。", author: "陶渊明", category: "贫贱与富贵"),
        Quote(text: "其言兹若人之俦乎？衔觞赋诗，以乐其志。", author: "陶渊明", category: "赋诗与乐志"),
        Quote(text: "无怀氏之民欤？葛天氏之民欤？", author: "陶渊明", category: "上古之民"),
        Quote(text: "晋太元中，武陵人捕鱼为业。", author: "陶渊明", category: "桃花源记"),
        Quote(text: "缘溪行，忘路之远近。", author: "陶渊明", category: "缘溪与忘路"),
        Quote(text: "忽逢桃花林，夹岸数百步，中无杂树，芳草鲜美，落英缤纷。", author: "陶渊明", category: "桃花林"),
        Quote(text: "渔人甚异之，复前行，欲穷其林。", author: "陶渊明", category: "异之与穷林"),
        Quote(text: "林尽水源，便得一山，山有小口，仿佛若有光。", author: "陶渊明", category: "林尽与山"),
        Quote(text: "便舍船，从口入。初极狭，才通人。", author: "陶渊明", category: "舍船与入山"),
        Quote(text: "复行数十步，豁然开朗。", author: "陶渊明", category: "豁然开朗"),
        Quote(text: "土地平旷，屋舍俨然，有良田、美池、桑竹之属。", author: "陶渊明", category: "桃花源"),
        Quote(text: "阡陌交通，鸡犬相闻。", author: "陶渊明", category: "田园景象"),
        Quote(text: "其中往来种作，男女衣着，悉如外人。", author: "陶渊明", category: "桃源中人"),
        Quote(text: "黄发垂髫，并怡然自乐。", author: "陶渊明", category: "老幼怡然"),
        Quote(text: "见渔人，乃大惊，问所从来。具答之。", author: "陶渊明", category: "见渔人"),
        Quote(text: "便要还家，设酒杀鸡作食。", author: "陶渊明", category: "邀还家"),
        Quote(text: "村中闻有此人，咸来问讯。", author: "陶渊明", category: "咸来问讯"),
        Quote(text: "自云先世避秦时乱，率妻子邑人来此绝境，不复出焉，遂与外人间隔。", author: "陶渊明", category: "避秦来此"),
        Quote(text: "问今是何世，乃不知有汉，无论魏晋。", author: "陶渊明", category: "不知汉魏"),
        Quote(text: "此人一一为具言所闻，皆叹惋。", author: "陶渊明", category: "具言所闻"),
        Quote(text: "余人各复延至其家，皆出酒食。", author: "陶渊明", category: "各延至家"),
        Quote(text: "停数日，辞去。", author: "陶渊明", category: "停数日辞去"),
        Quote(text: "此中人语云：不足为外人道也。", author: "陶渊明", category: "不足为外人道"),
        Quote(text: "既出，得其船，便扶向路，处处志之。", author: "陶渊明", category: "既出志之"),
        Quote(text: "及郡下，诣太守，说如此。", author: "陶渊明", category: "诣太守"),
        Quote(text: "太守即遣人随其往，寻向所志，遂迷，不复得路。", author: "陶渊明", category: "寻向所志遂迷"),
        Quote(text: "南阳刘子骥，高尚士也，闻之，欣然规往。", author: "陶渊明", category: "刘子骥"),
        Quote(text: "未果，寻病终，后遂无问津者。", author: "陶渊明", category: "无问津者"),
        Quote(text: "天地有大美而不言。", author: "庄子", category: "天地大美"),
        Quote(text: "北冥有鱼，其名为鲲。鲲之大，不知其几千里也。", author: "庄子", category: "鲲鹏"),
        Quote(text: "化而为鸟，其名为鹏。鹏之背，不知其几千里也。", author: "庄子", category: "大鹏"),
        Quote(text: "怒而飞，其翼若垂天之云。", author: "庄子", category: "鹏之翼"),
        Quote(text: "水击三千里，抟扶摇而上者九万里。", author: "庄子", category: "鹏之飞"),
        Quote(text: "野马也，尘埃也，生物之以息相吹也。", author: "庄子", category: "野马尘埃"),
        Quote(text: "天之苍苍，其正色邪？其远而无所至极邪？", author: "庄子", category: "天之苍苍"),
        Quote(text: "其视下也，亦若是则已矣。", author: "庄子", category: "鹏视下"),
        Quote(text: "且夫水之积也不厚，则其负大舟也无力。", author: "庄子", category: "水厚负舟"),
        Quote(text: "覆杯水于坳堂之上，则芥为之舟；置杯焉则胶，水浅而舟大也。", author: "庄子", category: "杯水芥舟"),
        Quote(text: "风之积也不厚，则其负大翼也无力。", author: "庄子", category: "风厚负翼"),
        Quote(text: "故九万里，则风斯在下矣，而后乃今培风。", author: "庄子", category: "培风"),
        Quote(text: "背负青天，而莫之夭阏者，而后乃今将图南。", author: "庄子", category: "图南"),
        Quote(text: "蜩与学鸠笑之曰：我决起而飞，抢榆枋而止。", author: "庄子", category: "蜩与学鸠"),
        Quote(text: "时则不至，而控于地而已矣，奚以之九万里而南为？", author: "庄子", category: "笑大鹏"),
        Quote(text: "适莽苍者，三餐而反，腹犹果然。", author: "庄子", category: "适莽苍"),
        Quote(text: "适百里者，宿舂粮；适千里者，三月聚粮。", author: "庄子", category: "适千里"),
        Quote(text: "之二虫又何知！", author: "庄子", category: "二虫何知"),
        Quote(text: "小知不及大知，小年不及大年。", author: "庄子", category: "小知大知"),
        Quote(text: "奚以知其然也？朝菌不知晦朔，蟪蛄不知春秋，此小年也。", author: "庄子", category: "小年"),
        Quote(text: "楚之南有冥灵者，以五百岁为春，五百岁为秋。", author: "庄子", category: "冥灵大年"),
        Quote(text: "上古有大椿者，以八千岁为春，八千岁为秋，此大年也。", author: "庄子", category: "大椿大年"),
        Quote(text: "而彭祖乃今以久特闻，众人匹之，不亦悲乎！", author: "庄子", category: "彭祖"),
        Quote(text: "汤之问棘也是已。", author: "庄子", category: "汤问棘"),
        Quote(text: "穷发之北，有冥海者，天池也。", author: "庄子", category: "穷发北海"),
        Quote(text: "有鱼焉，其广数千里，未有知其修者，其名为鲲。", author: "庄子", category: "北冥之鲲"),
        Quote(text: "有鸟焉，其名为鹏，背若泰山，翼若垂天之云。", author: "庄子", category: "鹏之背"),
        Quote(text: "抟扶摇羊角而上者九万里，绝云气，负青天。", author: "庄子", category: "抟扶摇"),
        Quote(text: "然后图南，且适南冥也。", author: "庄子", category: "适南冥"),
        Quote(text: "斥鷃笑之曰：彼且奚适也？", author: "庄子", category: "斥鷃笑鹏"),
        Quote(text: "我腾跃而上，不过数仞而下，翱翔蓬蒿之间，此亦飞之至也。", author: "庄子", category: "斥鷃之飞"),
        Quote(text: "而彼且奚适也？此小大之辩也。", author: "庄子", category: "小大之辩"),
        Quote(text: "故夫知效一官，行比一乡，德合一君，而征一国者，其自视也，亦若此矣。", author: "庄子", category: "知效一官"),
        Quote(text: "而宋荣子犹然笑之。", author: "庄子", category: "宋荣子笑之"),
        Quote(text: "且举世誉之而不加劝，举世非之而不加沮。", author: "庄子", category: "宋荣子"),
        Quote(text: "定乎内外之分，辩乎荣辱之境，斯已矣。", author: "庄子", category: "内外荣辱"),
        Quote(text: "彼其于世，未数数然也。虽然，犹有未树也。", author: "庄子", category: "未树"),
        Quote(text: "夫列子御风而行，泠然善也，旬有五日而后反。", author: "庄子", category: "列子御风"),
        Quote(text: "彼于致福者，未数数然也。此虽免乎行，犹有所待者也。", author: "庄子", category: "有所待"),
        Quote(text: "若夫乘天地之正，而御六气之辩，以游无穷者，彼且恶乎待哉？", author: "庄子", category: "游无穷"),
        Quote(text: "故曰：至人无己，神人无功，圣人无名。", author: "庄子", category: "至人神人圣人"),
        Quote(text: "吾生也有涯，而知也无涯。", author: "庄子", category: "生有涯知无涯"),
        Quote(text: "以有涯随无涯，殆已！", author: "庄子", category: "以有涯随无涯"),
        Quote(text: "已而为知者，殆而已矣！", author: "庄子", category: "殆而已矣"),
        Quote(text: "为善无近名，为恶无近刑。", author: "庄子", category: "为善为恶"),
        Quote(text: "缘督以为经，可以保身，可以全生，可以养亲，可以尽年。", author: "庄子", category: "缘督为经"),
        Quote(text: "庖丁为文惠君解牛。", author: "庄子", category: "庖丁解牛"),
        Quote(text: "手之所触，肩之所倚，足之所履，膝之所踦。", author: "庄子", category: "解牛动作"),
        Quote(text: "砉然向然，奏刀騞然，莫不中音。", author: "庄子", category: "解牛之声"),
        Quote(text: "合于桑林之舞，乃中经首之会。", author: "庄子", category: "合于乐舞"),
        Quote(text: "文惠君曰：嘻，善哉！技盖至此乎？", author: "庄子", category: "文惠君叹"),
        Quote(text: "庖丁释刀对曰：臣之所好者，道也，进乎技矣。", author: "庄子", category: "道进乎技"),
        Quote(text: "始臣之解牛之时，所见无非牛者。", author: "庄子", category: "始解牛"),
        Quote(text: "三年之后，未尝见全牛也。", author: "庄子", category: "未见全牛"),
        Quote(text: "方今之时，臣以神遇而不以目视，官知止而神欲行。", author: "庄子", category: "神遇"),
        Quote(text: "依乎天理，批大郤，导大窾，因其固然。", author: "庄子", category: "依乎天理"),
        Quote(text: "技经肯綮之未尝，而况大軱乎！", author: "庄子", category: "未尝肯綮"),
        Quote(text: "良庖岁更刀，割也；族庖月更刀，折也。", author: "庄子", category: "良庖族庖"),
        Quote(text: "今臣之刀十九年矣，所解数千牛矣，而刀刃若新发于硎。", author: "庄子", category: "十九年之刀"),
        Quote(text: "彼节者有间，而刀刃者无厚。", author: "庄子", category: "节有间刀无厚"),
        Quote(text: "以无厚入有间，恢恢乎其于游刃必有余地矣！", author: "庄子", category: "游刃有余"),
        Quote(text: "是以十九年而刀刃若新发于硎。", author: "庄子", category: "刀刃若新"),
        Quote(text: "虽然，每至于族，吾见其难为，怵然为戒，视为止，行为迟。", author: "庄子", category: "怵然为戒"),
        Quote(text: "动刀甚微，謋然已解，如土委地。", author: "庄子", category: "謋然已解"),
        Quote(text: "提刀而立，为之四顾，为之踌躇满志，善刀而藏之。", author: "庄子", category: "踌躇满志"),
        Quote(text: "文惠君曰：善哉！吾闻庖丁之言，得养生焉。", author: "庄子", category: "得养生"),
        Quote(text: "独与天地精神往来。", author: "庄子", category: "天地精神"),
        Quote(text: "至人神矣！大泽焚而不能热，河汉冱而不能寒，疾雷破山、风振海而不能惊。", author: "庄子", category: "至人神矣"),
        Quote(text: "若然者，乘云气，骑日月，而游乎四海之外。", author: "庄子", category: "游乎四海之外"),
        Quote(text: "死生无变于己，而况利害之端乎！", author: "庄子", category: "死生无变于己"),
        Quote(text: "相濡以沫，不如相忘于江湖。", author: "庄子", category: "相忘江湖"),
        Quote(text: "与其誉尧而非桀也，不如两忘而化其道。", author: "庄子", category: "两忘化道"),
        Quote(text: "夫大块载我以形，劳我以生，佚我以老，息我以死。", author: "庄子", category: "大块载我"),
        Quote(text: "故善吾生者，乃所以善吾死也。", author: "庄子", category: "善生善死"),
        Quote(text: "人生天地之间，若白驹之过隙，忽然而已。", author: "庄子", category: "人生短暂"),
        Quote(text: "注然勃然，莫不出焉；油然寥然，莫不入焉。", author: "庄子", category: "生死出入"),
        Quote(text: "已化而生，又化而死，生物哀之，人类悲之。", author: "庄子", category: "生死"),
        Quote(text: "解其天弢，堕其天袠，纷乎宛乎，魂魄将往，乃身从之，乃大归乎！", author: "庄子", category: "大归"),
        Quote(text: "不形之形，形之不形，是人之所同知也。", author: "庄子", category: "形与不形"),
        Quote(text: "非将至之所务也，此众人之所同论也。", author: "庄子", category: "众人所论"),
        Quote(text: "彼至则不论，论则不至。", author: "庄子", category: "至则不论"),
        Quote(text: "明见无值，辩不若默。", author: "庄子", category: "辩不若默"),
        Quote(text: "道不可闻，闻不若塞，此之谓大得。", author: "庄子", category: "大得"),
        Quote(text: "道生一，一生二，二生三，三生万物。", author: "老子", category: "宇宙与道"),
        Quote(text: "人法地，地法天，天法道，道法自然。", author: "老子", category: "自然与道"),
        Quote(text: "上善若水。水善利万物而不争。", author: "老子", category: "上善若水"),
        Quote(text: "处众人之所恶，故几于道。", author: "老子", category: "处众人之所恶"),
        Quote(text: "居善地，心善渊，与善仁，言善信，政善治，事善能，动善时。", author: "老子", category: "七善"),
        Quote(text: "夫唯不争，故无尤。", author: "老子", category: "不争无尤"),
        Quote(text: "持而盈之，不如其已。", author: "老子", category: "持盈"),
        Quote(text: "揣而锐之，不可长保。", author: "老子", category: "揣锐"),
        Quote(text: "金玉满堂，莫之能守。", author: "老子", category: "金玉满堂"),
        Quote(text: "富贵而骄，自遗其咎。", author: "老子", category: "富贵而骄"),
        Quote(text: "功遂身退，天之道也。", author: "老子", category: "功遂身退"),
        Quote(text: "载营魄抱一，能无离乎？", author: "老子", category: "载营魄抱一"),
        Quote(text: "专气致柔，能如婴儿乎？", author: "老子", category: "专气致柔"),
        Quote(text: "涤除玄鉴，能无疵乎？", author: "老子", category: "涤除玄鉴"),
        Quote(text: "爱民治国，能无为乎？", author: "老子", category: "爱民治国"),
        Quote(text: "天门开阖，能为雌乎？", author: "老子", category: "天门开阖"),
        Quote(text: "明白四达，能无知乎？", author: "老子", category: "明白四达"),
        Quote(text: "生之畜之，生而不有，为而不恃，长而不宰，是谓玄德。", author: "老子", category: "玄德"),
        Quote(text: "三十辐共一毂，当其无，有车之用。", author: "老子", category: "车轮之用"),
        Quote(text: "埏埴以为器，当其无，有器之用。", author: "老子", category: "陶器之用"),
        Quote(text: "凿户牖以为室，当其无，有室之用。", author: "老子", category: "室之用"),
        Quote(text: "故有之以为利，无之以为用。", author: "老子", category: "有无之用"),
        Quote(text: "五色令人目盲；五音令人耳聋；五味令人口爽。", author: "老子", category: "五色五音五味"),
        Quote(text: "驰骋畋猎，令人心发狂；难得之货，令人行妨。", author: "老子", category: "畋猎难得之货"),
        Quote(text: "是以圣人为腹不为目，故去彼取此。", author: "老子", category: "为腹不为目"),
        Quote(text: "宠辱若惊，贵大患若身。", author: "老子", category: "宠辱若惊"),
        Quote(text: "何谓宠辱若惊？宠为下，得之若惊，失之若惊，是谓宠辱若惊。", author: "老子", category: "宠辱"),
        Quote(text: "何谓贵大患若身？吾所以有大患者，为吾有身，及吾无身，吾有何患？", author: "老子", category: "贵大患若身"),
        Quote(text: "故贵以身为天下，若可寄天下；爱以身为天下，若可托天下。", author: "老子", category: "贵身爱身"),
        Quote(text: "视之不见，名曰夷；听之不闻，名曰希；搏之不得，名曰微。", author: "老子", category: "夷希微"),
        Quote(text: "此三者不可致诘，故混而为一。", author: "老子", category: "混而为一"),
        Quote(text: "其上不皦，其下不昧，绳绳兮不可名，复归于无物。", author: "老子", category: "无物"),
        Quote(text: "是谓无状之状，无物之象，是谓惚恍。", author: "老子", category: "惚恍"),
        Quote(text: "迎之不见其首，随之不见其后。", author: "老子", category: "不见首尾"),
        Quote(text: "执古之道，以御今之有。", author: "老子", category: "执古御今"),
        Quote(text: "能知古始，是谓道纪。", author: "老子", category: "道纪"),
        Quote(text: "古之善为士者，微妙玄通，深不可识。", author: "老子", category: "善为士者"),
        Quote(text: "夫唯不可识，故强为之容。", author: "老子", category: "强为之容"),
        Quote(text: "豫兮若冬涉川；犹兮若畏四邻；俨兮其若客；涣兮其若冰之将释。", author: "老子", category: "古士容"),
        Quote(text: "敦兮其若朴；旷兮其若谷；混兮其若浊。", author: "老子", category: "朴谷浊"),
        Quote(text: "孰能浊以静之徐清？孰能安以动之徐生？", author: "老子", category: "浊静清安动生"),
        Quote(text: "保此道者，不欲盈。", author: "老子", category: "不欲盈"),
        Quote(text: "夫唯不盈，故能蔽而新成。", author: "老子", category: "蔽而新成"),
        Quote(text: "致虚极，守静笃。", author: "老子", category: "致虚守静"),
        Quote(text: "万物并作，吾以观复。", author: "老子", category: "观复"),
        Quote(text: "夫物芸芸，各复归其根。", author: "老子", category: "归其根"),
        Quote(text: "归根曰静，静曰复命。", author: "老子", category: "归根复命"),
        Quote(text: "复命曰常，知常曰明。", author: "老子", category: "复命知常"),
        Quote(text: "不知常，妄作凶。", author: "老子", category: "不知常妄作凶"),
        Quote(text: "知常容，容乃公，公乃全，全乃天，天乃道，道乃久，没身不殆。", author: "老子", category: "知容公道天久"),
        Quote(text: "太上，下知有之；其次，亲而誉之；其次，畏之；其次，侮之。", author: "老子", category: "太上"),
        Quote(text: "信不足焉，有不信焉。", author: "老子", category: "信不足"),
        Quote(text: "悠兮其贵言。功成事遂，百姓皆谓我自然。", author: "老子", category: "自然"),
        Quote(text: "大道废，有仁义；智慧出，有大伪。", author: "老子", category: "大道废有仁义"),
        Quote(text: "六亲不和，有孝慈；国家昏乱，有忠臣。", author: "老子", category: "六亲不和有孝慈"),
        Quote(text: "绝圣弃智，民利百倍；绝仁弃义，民复孝慈；绝巧弃利，盗贼无有。", author: "老子", category: "绝圣弃智"),
        Quote(text: "此三者以为文，不足。故令有所属：见素抱朴，少私寡欲。", author: "老子", category: "见素抱朴"),
        Quote(text: "绝学无忧。", author: "老子", category: "绝学无忧"),
        Quote(text: "唯之与阿，相去几何？美之与恶，相去若何？", author: "老子", category: "唯阿美恶"),
        Quote(text: "人之所畏，不可不畏。", author: "老子", category: "人之所畏"),
        Quote(text: "荒兮，其未央哉！", author: "老子", category: "荒兮未央"),
        Quote(text: "众人熙熙，如享太牢，如春登台。", author: "老子", category: "众人熙熙"),
        Quote(text: "我独泊兮，其未兆；沌沌兮，如婴儿之未孩。", author: "老子", category: "我独泊兮"),
        Quote(text: "儽儽兮，若无所归。", author: "老子", category: "儽儽兮"),
        Quote(text: "众人皆有余，而我独若遗。我愚人之心也哉！", author: "老子", category: "独若遗"),
        Quote(text: "俗人昭昭，我独昏昏。俗人察察，我独闷闷。", author: "老子", category: "昭昭昏昏"),
        Quote(text: "澹兮其若海，飂兮若无止。", author: "老子", category: "澹兮飂兮"),
        Quote(text: "众人皆有以，而我独顽且鄙。", author: "老子", category: "独顽且鄙"),
        Quote(text: "我独异于人，而贵食母。", author: "老子", category: "贵食母"),
        Quote(text: "孔德之容，惟道是从。", author: "老子", category: "孔德之容"),
        Quote(text: "道之为物，惟恍惟惚。", author: "老子", category: "道之为物"),
        Quote(text: "惚兮恍兮，其中有象；恍兮惚兮，其中有物。", author: "老子", category: "惚恍中有物"),
        Quote(text: "窈兮冥兮，其中有精；其精甚真，其中有信。", author: "老子", category: "窈冥有精"),
        Quote(text: "自今及古，其名不去，以阅众甫。", author: "老子", category: "以阅众甫"),
        Quote(text: "吾何以知众甫之状哉？以此。", author: "老子", category: "以此知之"),
        Quote(text: "曲则全，枉则直，洼则盈，敝则新，少则得，多则惑。", author: "老子", category: "曲全枉直"),
        Quote(text: "是以圣人抱一为天下式。", author: "老子", category: "抱一为天下式"),
        Quote(text: "不自见，故明；不自是，故彰；不自伐，故有功；不自矜，故长。", author: "老子", category: "不自见故明"),
        Quote(text: "夫唯不争，故天下莫能与之争。", author: "老子", category: "不争莫能争"),
        Quote(text: "古之所谓曲则全者，岂虚言哉！诚全而归之。", author: "老子", category: "诚全而归之"),
        Quote(text: "希言自然。", author: "老子", category: "希言自然"),
        Quote(text: "故飘风不终朝，骤雨不终日。", author: "老子", category: "飘风骤雨"),
        Quote(text: "孰为此者？天地。天地尚不能久，而况于人乎？", author: "老子", category: "天地尚不能久"),
        Quote(text: "故从事于道者，同于道；德者，同于德；失者，同于失。", author: "老子", category: "从事于道"),
        Quote(text: "同于道者，道亦乐得之；同于德者，德亦乐得之；同于失者，失亦乐得之。", author: "老子", category: "同于道德"),
        Quote(text: "信不足焉，有不信焉。", author: "老子", category: "信不足焉"),
        Quote(text: "企者不立，跨者不行。", author: "老子", category: "企者不立"),
        Quote(text: "自见者不明，自是者不彰，自伐者无功，自矜者不长。", author: "老子", category: "自见自是"),
        Quote(text: "其在道也，曰余食赘行。物或恶之，故有道者不处。", author: "老子", category: "余食赘行"),
        Quote(text: "有物混成，先天地生。", author: "老子", category: "有物混成"),
        Quote(text: "寂兮寥兮，独立而不改，周行而不殆，可以为天地母。", author: "老子", category: "寂兮寥兮"),
        Quote(text: "吾不知其名，强字之曰道，强为之名曰大。", author: "老子", category: "强字之曰道"),
        Quote(text: "大曰逝，逝曰远，远曰反。", author: "老子", category: "大逝远反"),
        Quote(text: "故道大，天大，地大，人亦大。", author: "老子", category: "四大"),
        Quote(text: "域中有四大，而人居其一焉。", author: "老子", category: "域中四大"),
        Quote(text: "人法地，地法天，天法道，道法自然。", author: "老子", category: "道法自然"),
        Quote(text: "重为轻根，静为躁君。", author: "老子", category: "重静根君"),
        Quote(text: "是以君子终日行不离辎重。", author: "老子", category: "不离辎重"),
        Quote(text: "虽有荣观，燕处超然。", author: "老子", category: "燕处超然"),
        Quote(text: "奈何万乘之主，而以身轻天下？", author: "老子", category: "以身轻天下"),
        Quote(text: "轻则失根，躁则失君。", author: "老子", category: "失根失君"),
        Quote(text: "善行无辙迹，善言无瑕谪。", author: "老子", category: "善行善言"),
        Quote(text: "善数不用筹策，善闭无关楗而不可开。", author: "老子", category: "善数善闭"),
        Quote(text: "善结无绳约而不可解。", author: "老子", category: "善结"),
        Quote(text: "是以圣人常善救人，故无弃人；常善救物，故无弃物。", author: "老子", category: "善救人救物"),
        Quote(text: "是谓袭明。", author: "老子", category: "袭明"),
        Quote(text: "故善人者，不善人之师；不善人者，善人之资。", author: "老子", category: "善人不善人"),
        Quote(text: "不贵其师，不爱其资，虽智大迷，是谓要妙。", author: "老子", category: "要妙"),
        Quote(text: "知其雄，守其雌，为天下溪。", author: "老子", category: "知雄守雌"),
        Quote(text: "为天下溪，常德不离，复归于婴儿。", author: "老子", category: "复归婴儿"),
        Quote(text: "知其白，守其黑，为天下式。", author: "老子", category: "知白守黑"),
        Quote(text: "为天下式，常德不忒，复归于无极。", author: "老子", category: "复归无极"),
        Quote(text: "知其荣，守其辱，为天下谷。", author: "老子", category: "知荣守辱"),
        Quote(text: "为天下谷，常德乃足，复归于朴。", author: "老子", category: "复归于朴"),
        Quote(text: "朴散则为器，圣人用之，则为官长。", author: "老子", category: "朴散为器"),
        Quote(text: "故大制不割。", author: "老子", category: "大制不割"),
        Quote(text: "将欲取天下而为之，吾见其不得已。", author: "老子", category: "取天下"),
        Quote(text: "天下神器，不可为也，不可执也。", author: "老子", category: "天下神器"),
        Quote(text: "为者败之，执者失之。", author: "老子", category: "为败执失"),
        Quote(text: "故物或行或随，或歔或吹，或强或羸，或载或隳。", author: "老子", category: "物或行随"),
        Quote(text: "是以圣人去甚，去奢，去泰。", author: "老子", category: "去甚去奢"),
        Quote(text: "以道佐人主者，不以兵强天下。", author: "老子", category: "以道佐主"),
        Quote(text: "其事好还。", author: "老子", category: "其事好还"),
        Quote(text: "师之所处，荆棘生焉。大军之后，必有凶年。", author: "老子", category: "师之所处"),
        Quote(text: "善有果而已，不敢以取强。", author: "老子", category: "善有果而已"),
        Quote(text: "果而勿矜，果而勿伐，果而勿骄。", author: "老子", category: "果而勿矜"),
        Quote(text: "果而不得已，果而勿强。", author: "老子", category: "果而勿强"),
        Quote(text: "物壮则老，是谓不道，不道早已。", author: "老子", category: "物壮则老"),
        Quote(text: "夫兵者，不祥之器，物或恶之，故有道者不处。", author: "老子", category: "兵者不祥"),
        Quote(text: "君子居则贵左，用兵则贵右。", author: "老子", category: "贵左贵右"),
        Quote(text: "兵者不祥之器，非君子之器。", author: "老子", category: "非君子器"),
        Quote(text: "不得已而用之，恬淡为上。", author: "老子", category: "恬淡为上"),
        Quote(text: "胜而不美，而美之者，是乐杀人。", author: "老子", category: "胜而不美"),
        Quote(text: "夫乐杀人者，则不可得志于天下矣。", author: "老子", category: "乐杀人"),
        Quote(text: "吉事尚左，凶事尚右。", author: "老子", category: "吉凶左右"),
        Quote(text: "偏将军居左，上将军居右，言以丧礼处之。", author: "老子", category: "丧礼处之"),
        Quote(text: "杀人之众，以悲哀泣之，战胜以丧礼处之。", author: "老子", category: "悲哀泣之"),
        Quote(text: "道常无名。", author: "老子", category: "道常无名"),
        Quote(text: "朴虽小，天下莫能臣。", author: "老子", category: "朴虽小"),
        Quote(text: "侯王若能守之，万物将自宾。", author: "老子", category: "万物自宾"),
        Quote(text: "天地相合，以降甘露，民莫之令而自均。", author: "老子", category: "天地相合"),
        Quote(text: "始制有名，名亦既有，夫亦将知止，知止可以不殆。", author: "老子", category: "始制有名"),
        Quote(text: "譬道之在天下，犹川谷之于江海。", author: "老子", category: "道之在天下"),
        Quote(text: "知人者智，自知者明。", author: "老子", category: "知人自知"),
        Quote(text: "胜人者有力，自胜者强。", author: "老子", category: "胜人胜己"),
        Quote(text: "知足者富，强行者有志。", author: "老子", category: "知足强行"),
        Quote(text: "不失其所者久，死而不亡者寿。", author: "老子", category: "死而不亡"),
        Quote(text: "道泛兮，其可左右。", author: "老子", category: "道泛兮"),
        Quote(text: "万物恃之以生而不辞，功成而不有。", author: "老子", category: "不辞不有"),
        Quote(text: "衣养万物而不为主，常无欲，可名于小。", author: "老子", category: "衣养万物"),
        Quote(text: "万物归焉而不为主，可名为大。", author: "老子", category: "万物归焉"),
        Quote(text: "以其终不自为大，故能成其大。", author: "老子", category: "成其大"),
        Quote(text: "执大象，天下往。", author: "老子", category: "执大象"),
        Quote(text: "往而不害，安平太。", author: "老子", category: "安平太"),
        Quote(text: "乐与饵，过客止。", author: "老子", category: "乐与饵"),
        Quote(text: "道之出口，淡乎其无味。", author: "老子", category: "淡乎无味"),
        Quote(text: "视之不足见，听之不足闻，用之不足既。", author: "老子", category: "视听用"),
        Quote(text: "将欲歙之，必固张之；将欲弱之，必固强之。", author: "老子", category: "歙张弱强"),
        Quote(text: "将欲废之，必固兴之；将欲取之，必固与之。", author: "老子", category: "废兴取与"),
        Quote(text: "是谓微明。", author: "老子", category: "微明"),
        Quote(text: "柔弱胜刚强。", author: "老子", category: "柔弱胜刚"),
        Quote(text: "鱼不可脱于渊，国之利器不可以示人。", author: "老子", category: "鱼不可脱渊"),
        Quote(text: "道常无为而无不为。", author: "老子", category: "无为无不为"),
        Quote(text: "侯王若能守之，万物将自化。", author: "老子", category: "万物自化"),
        Quote(text: "化而欲作，吾将镇之以无名之朴。", author: "老子", category: "无名之朴"),
        Quote(text: "无名之朴，夫亦将不欲。", author: "老子", category: "不欲"),
        Quote(text: "不欲以静，天下将自正。", author: "老子", category: "天下自正"),
        Quote(text: "上德不德，是以有德；下德不失德，是以无德。", author: "老子", category: "上下德"),
        Quote(text: "上德无为而无以为，下德无为而有以为。", author: "老子", category: "上德下德"),
        Quote(text: "上仁为之而无以为，上义为之而有以为。", author: "老子", category: "上仁上义"),
        Quote(text: "上礼为之而莫之应，则攘臂而扔之。", author: "老子", category: "上礼"),
        Quote(text: "故失道而后德，失德而后仁，失仁而后义，失义而后礼。", author: "老子", category: "失道德仁义礼"),
        Quote(text: "夫礼者，忠信之薄，而乱之首。", author: "老子", category: "忠信之薄"),
        Quote(text: "前识者，道之华，而愚之始。", author: "老子", category: "前识者"),
        Quote(text: "是以大丈夫处其厚，不居其薄；处其实，不居其华。", author: "老子", category: "处厚处实"),
        Quote(text: "故去彼取此。", author: "老子", category: "去彼取此"),
        Quote(text: "昔之得一者：天得一以清，地得一以宁。", author: "老子", category: "得一"),
        Quote(text: "神得一以灵，谷得一以盈，万物得一以生。", author: "老子", category: "神谷得一"),
        Quote(text: "侯王得一以为天下正。", author: "老子", category: "侯王得一"),
        Quote(text: "其致之也，谓天无以清，将恐裂；地无以宁，将恐发。", author: "老子", category: "致之"),
        Quote(text: "神无以灵，将恐歇；谷无以盈，将恐竭。", author: "老子", category: "神谷"),
        Quote(text: "万物无以生，将恐灭；侯王无以正，将恐蹶。", author: "老子", category: "万物侯王"),
        Quote(text: "故贵以贱为本，高以下为基。", author: "老子", category: "贵贱高下"),
        Quote(text: "是以侯王自称孤、寡、不谷。", author: "老子", category: "自称孤寡"),
        Quote(text: "此非以贱为本邪？非乎？", author: "老子", category: "以贱为本"),
        Quote(text: "故致数舆无舆。", author: "老子", category: "数舆无舆"),
        Quote(text: "是故不欲琭琭如玉，珞珞如石。", author: "老子", category: "不欲琭珞"),
        Quote(text: "反者道之动，弱者道之用。", author: "老子", category: "反动弱用"),
        Quote(text: "天下万物生于有，有生于无。", author: "老子", category: "有生于无"),
        Quote(text: "上士闻道，勤而行之；中士闻道，若存若亡。", author: "老子", category: "上士中士"),
        Quote(text: "下士闻道，大笑之。不笑不足以为道。", author: "老子", category: "下士闻道"),
        Quote(text: "故建言有之：明道若昧，进道若退。", author: "老子", category: "明道若昧"),
        Quote(text: "夷道若颣，上德若谷，大白若辱。", author: "老子", category: "夷道若颣"),
        Quote(text: "广德若不足，建德若偷，质真若渝。", author: "老子", category: "广德建德"),
        Quote(text: "大方无隅，大器晚成，大音希声，大象无形。", author: "老子", category: "大方大器"),
        Quote(text: "道隐无名。", author: "老子", category: "道隐无名"),
        Quote(text: "夫唯道，善贷且成。", author: "老子", category: "善贷且成"),
        Quote(text: "道生一，一生二，二生三，三生万物。", author: "老子", category: "道生万物"),
        Quote(text: "万物负阴而抱阳，冲气以为和。", author: "老子", category: "负阴抱阳"),
        Quote(text: "人之所恶，唯孤、寡、不谷，而王公以为称。", author: "老子", category: "人之所恶"),
        Quote(text: "故物或损之而益，或益之而损。", author: "老子", category: "损益"),
        Quote(text: "人之所教，我亦教之。", author: "老子", category: "人之所教"),
        Quote(text: "强梁者不得其死，吾将以为教父。", author: "老子", category: "强梁者"),
        Quote(text: "天下之至柔，驰骋天下之至坚。", author: "老子", category: "至柔至坚"),
        Quote(text: "无有入无间，吾是以知无为之有益。", author: "老子", category: "无有入无间"),
        Quote(text: "不言之教，无为之益，天下希及之。", author: "老子", category: "不言之教"),
        Quote(text: "名与身孰亲？身与货孰多？", author: "老子", category: "名身孰亲"),
        Quote(text: "得与亡孰病？", author: "老子", category: "得亡孰病"),
        Quote(text: "是故甚爱必大费，多藏必厚亡。", author: "老子", category: "甚爱多藏"),
        Quote(text: "知足不辱，知止不殆，可以长久。", author: "老子", category: "知足知止"),
        Quote(text: "大成若缺，其用不弊。", author: "老子", category: "大成若缺"),
        Quote(text: "大盈若冲，其用不穷。", author: "老子", category: "大盈若冲"),
        Quote(text: "大直若屈，大巧若拙，大辩若讷。", author: "老子", category: "大直大巧"),
        Quote(text: "躁胜寒，静胜热。", author: "老子", category: "躁静"),
        Quote(text: "清静为天下正。", author: "老子", category: "清静为正"),
        Quote(text: "天下有道，却走马以粪。", author: "老子", category: "天下有道"),
        Quote(text: "天下无道，戎马生于郊。", author: "老子", category: "天下无道"),
        Quote(text: "祸莫大于不知足，咎莫大于欲得。", author: "老子", category: "祸咎"),
        Quote(text: "故知足之足，常足矣。", author: "老子", category: "知足常足"),
        Quote(text: "不出户，知天下；不窥牖，见天道。", author: "老子", category: "不出户"),
        Quote(text: "其出弥远，其知弥少。", author: "老子", category: "其出弥远"),
        Quote(text: "是以圣人不行而知，不见而明，不为而成。", author: "老子", category: "不行而知"),
        Quote(text: "为学日益，为道日损。", author: "老子", category: "为学为道"),
        Quote(text: "损之又损，以至于无为。", author: "老子", category: "损之又损"),
        Quote(text: "无为而无不为。", author: "老子", category: "无为无不为"),
        Quote(text: "取天下常以无事，及其有事，不足以取天下。", author: "老子", category: "取天下无事"),
        Quote(text: "圣人无常心，以百姓心为心。", author: "老子", category: "无常心"),
        Quote(text: "善者，吾善之；不善者，吾亦善之，德善。", author: "老子", category: "善者不善"),
        Quote(text: "信者，吾信之；不信者，吾亦信之，德信。", author: "老子", category: "信者不信"),
        Quote(text: "圣人在天下，歙歙焉，为天下浑其心。", author: "老子", category: "浑其心"),
        Quote(text: "百姓皆注其耳目，圣人皆孩之。", author: "老子", category: "孩之"),
        Quote(text: "出生入死。", author: "老子", category: "出生入死"),
        Quote(text: "生之徒十有三，死之徒十有三。", author: "老子", category: "生徒死徒"),
        Quote(text: "人之生，动之于死地，亦十有三。", author: "老子", category: "动之死地"),
        Quote(text: "夫何故？以其生生之厚。", author: "老子", category: "生生之厚"),
        Quote(text: "盖闻善摄生者，陆行不遇兕虎，入军不被甲兵。", author: "老子", category: "善摄生者"),
        Quote(text: "兕无所投其角，虎无所措其爪，兵无所容其刃。", author: "老子", category: "无所投措"),
        Quote(text: "夫何故？以其无死地。", author: "老子", category: "无死地"),
        Quote(text: "道生之，德畜之，物形之，势成之。", author: "老子", category: "道生德畜"),
        Quote(text: "是以万物莫不尊道而贵德。", author: "老子", category: "尊道贵德"),
        Quote(text: "道之尊，德之贵，夫莫之命而常自然。", author: "老子", category: "莫之命"),
        Quote(text: "故道生之，德畜之，长之育之，成之熟之。", author: "老子", category: "长育成熟"),
        Quote(text: "养之覆之。", author: "老子", category: "养覆"),
        Quote(text: "生而不有，为而不恃，长而不宰。", author: "老子", category: "生为长"),
        Quote(text: "是谓玄德。", author: "老子", category: "玄德"),
        Quote(text: "天下有始，以为天下母。", author: "老子", category: "天下有始"),
        Quote(text: "既得其母，以知其子；既知其子，复守其母。", author: "老子", category: "母子"),
        Quote(text: "没身不殆。", author: "老子", category: "没身不殆"),
        Quote(text: "塞其兑，闭其门，终身不勤。", author: "老子", category: "塞兑闭门"),
        Quote(text: "开其兑，济其事，终身不救。", author: "老子", category: "开兑济事"),
        Quote(text: "见小曰明，守柔曰强。", author: "老子", category: "见小明守柔强"),
        Quote(text: "用其光，复归其明，无遗身殃，是为习常。", author: "老子", category: "用其光"),
        Quote(text: "使我介然有知，行于大道，唯施是畏。", author: "老子", category: "介然有知"),
        Quote(text: "大道甚夷，而人好径。", author: "老子", category: "大道甚夷"),
        Quote(text: "朝甚除，田甚芜，仓甚虚。", author: "老子", category: "朝田仓"),
        Quote(text: "服文彩，带利剑，厌饮食，财货有余，是谓盗夸。", author: "老子", category: "盗夸"),
        Quote(text: "非道也哉！", author: "老子", category: "非道也哉"),
        Quote(text: "善建者不拔，善抱者不脱，子孙以祭祀不辍。", author: "老子", category: "善建善抱"),
        Quote(text: "修之于身，其德乃真；修之于家，其德乃余。", author: "老子", category: "修身修家"),
        Quote(text: "修之于乡，其德乃长；修之于国，其德乃丰。", author: "老子", category: "修乡修国"),
        Quote(text: "修之于天下，其德乃普。", author: "老子", category: "修天下"),
        Quote(text: "故以身观身，以家观家，以乡观乡。", author: "老子", category: "以身观身"),
        Quote(text: "以国观国，以天下观天下。", author: "老子", category: "以国观国"),
        Quote(text: "吾何以知天下然哉？以此。", author: "老子", category: "以此知之"),
        Quote(text: "含德之厚，比于赤子。", author: "老子", category: "含德之厚"),
        Quote(text: "毒虫不螫，猛兽不据，攫鸟不搏。", author: "老子", category: "毒虫猛兽"),
        Quote(text: "骨弱筋柔而握固。", author: "老子", category: "骨弱筋柔"),
        Quote(text: "未知牝牡之合而全作，精之至也。", author: "老子", category: "精之至也"),
        Quote(text: "终日号而不嗄，和之至也。", author: "老子", category: "和之至也"),
        Quote(text: "知和曰常，知常曰明。", author: "老子", category: "知和知常"),
        Quote(text: "益生曰祥，心使气曰强。", author: "老子", category: "益心使气"),
        Quote(text: "物壮则老，谓之不道，不道早已。", author: "老子", category: "物壮则老"),
        Quote(text: "知者不言，言者不知。", author: "老子", category: "知者不言"),
        Quote(text: "塞其兑，闭其门，挫其锐，解其纷。", author: "老子", category: "塞兑闭门挫锐"),
        Quote(text: "和其光，同其尘，是谓玄同。", author: "老子", category: "玄同"),
        Quote(text: "故不可得而亲，不可得而疏。", author: "老子", category: "不可得亲疏"),
        Quote(text: "不可得而利，不可得而害。", author: "老子", category: "不可得利害"),
        Quote(text: "不可得而贵，不可得而贱。", author: "老子", category: "不可得贵贱"),
        Quote(text: "故为天下贵。", author: "老子", category: "天下贵"),
        Quote(text: "以正治国，以奇用兵，以无事取天下。", author: "老子", category: "正奇无事"),
        Quote(text: "吾何以知其然哉？以此。", author: "老子", category: "以此知然"),
        Quote(text: "天下多忌讳，而民弥贫；人多利器，国家滋昏。", author: "老子", category: "忌讳利器"),
        Quote(text: "人多伎巧，奇物滋起；法令滋彰，盗贼多有。", author: "老子", category: "伎巧法令"),
        Quote(text: "故圣人云：我无为，而民自化。", author: "老子", category: "我无为民自化"),
        Quote(text: "我好静，而民自正；我无事，而民自富。", author: "老子", category: "好静无事"),
        Quote(text: "我无欲，而民自朴。", author: "老子", category: "无欲自朴"),
        Quote(text: "其政闷闷，其民淳淳；其政察察，其民缺缺。", author: "老子", category: "闷闷察察"),
        Quote(text: "祸兮，福之所倚；福兮，祸之所伏。", author: "老子", category: "祸福倚伏"),
        Quote(text: "孰知其极？其无正也。", author: "老子", category: "孰知其极"),
        Quote(text: "正复为奇，善复为妖。", author: "老子", category: "正奇善妖"),
        Quote(text: "人之迷，其日固久。", author: "老子", category: "人之迷"),
        Quote(text: "是以圣人方而不割，廉而不刿。", author: "老子", category: "方廉"),
        Quote(text: "直而不肆，光而不耀。", author: "老子", category: "直光"),
        Quote(text: "治人事天，莫若啬。", author: "老子", category: "啬"),
        Quote(text: "夫唯啬，是谓早服；早服谓之重积德。", author: "老子", category: "早服重德"),
        Quote(text: "重积德则无不克；无不克则莫知其极。", author: "老子", category: "重积德"),
        Quote(text: "莫知其极，可以有国；有国之母，可以长久。", author: "老子", category: "有国长久"),
        Quote(text: "是谓深根固柢，长生久视之道。", author: "老子", category: "深根固柢"),
        Quote(text: "治大国，若烹小鲜。", author: "老子", category: "治大国"),
        Quote(text: "以道莅天下，其鬼不神。", author: "老子", category: "以道莅天下"),
        Quote(text: "非其鬼不神，其神不伤人；非其神不伤人，圣人亦不伤人。", author: "老子", category: "鬼不神"),
        Quote(text: "夫两不相伤，故德交归焉。", author: "老子", category: "两不相伤"),
        Quote(text: "大邦者下流，天下之牝，天下之交也。", author: "老子", category: "大邦下流"),
        Quote(text: "牝常以静胜牡，以静为下。", author: "老子", category: "牝胜牡"),
        Quote(text: "故大邦以下小邦，则取小邦；小邦以下大邦，则取大邦。", author: "老子", category: "大小邦"),
        Quote(text: "故或下以取，或下而取。", author: "老子", category: "下以取"),
        Quote(text: "大邦不过欲兼畜人，小邦不过欲入事人。", author: "老子", category: "兼畜入事"),
        Quote(text: "夫两者各得所欲，大者宜为下。", author: "老子", category: "大者宜下"),
        Quote(text: "道者万物之奥。", author: "老子", category: "万物之奥"),
        Quote(text: "善人之宝，不善人之所保。", author: "老子", category: "善人所保"),
        Quote(text: "美言可以市，尊行可以加人。", author: "老子", category: "美言尊行"),
        Quote(text: "人之不善，何弃之有？", author: "老子", category: "何弃之有"),
        Quote(text: "故立天子，置三公，虽有拱璧以先驷马，不如坐进此道。", author: "老子", category: "立天子"),
        Quote(text: "古之所以贵此道者何？", author: "老子", category: "贵此道"),
        Quote(text: "不曰：求以得，有罪以免邪？故为天下贵。", author: "老子", category: "求以免"),
        Quote(text: "为无为，事无事，味无味。", author: "老子", category: "为事味"),
        Quote(text: "大小多少，报怨以德。", author: "老子", category: "报怨以德"),
        Quote(text: "图难于其易，为大于其细。", author: "老子", category: "图难为大"),
        Quote(text: "天下难事，必作于易；天下大事，必作于细。", author: "老子", category: "难事大事"),
        Quote(text: "是以圣人终不为大，故能成其大。", author: "老子", category: "终不为大"),
        Quote(text: "夫轻诺必寡信，多易必多难。", author: "老子", category: "轻诺多易"),
        Quote(text: "是以圣人犹难之，故终无难矣。", author: "老子", category: "犹难之"),
        Quote(text: "其安易持，其未兆易谋。", author: "老子", category: "安持兆谋"),
        Quote(text: "其脆易泮，其微易散。", author: "老子", category: "脆微"),
        Quote(text: "为之于未有，治之于未乱。", author: "老子", category: "未有未乱"),
        Quote(text: "合抱之木，生于毫末；九层之台，起于累土。", author: "老子", category: "合抱九层"),
        Quote(text: "千里之行，始于足下。", author: "老子", category: "千里之行"),
        Quote(text: "为者败之，执者失之。", author: "老子", category: "为败执失"),
        Quote(text: "是以圣人无为故无败，无执故无失。", author: "老子", category: "无为无败"),
        Quote(text: "民之从事，常于几成而败之。", author: "老子", category: "几成而败"),
        Quote(text: "慎终如始，则无败事。", author: "老子", category: "慎终如始"),
        Quote(text: "是以圣人欲不欲，不贵难得之货。", author: "老子", category: "欲不欲"),
        Quote(text: "学不学，复众人之所过。", author: "老子", category: "学不学"),
        Quote(text: "以辅万物之自然而不敢为。", author: "老子", category: "辅万物自然"),
        Quote(text: "古之善为道者，非以明民，将以愚之。", author: "老子", category: "善为道者"),
        Quote(text: "民之难治，以其智多。", author: "老子", category: "民之难治"),
        Quote(text: "故以智治国，国之贼；不以智治国，国之福。", author: "老子", category: "以智治国"),
        Quote(text: "知此两者亦稽式。", author: "老子", category: "稽式"),
        Quote(text: "常知稽式，是谓玄德。", author: "老子", category: "玄德"),
        Quote(text: "玄德深矣，远矣，与物反矣，然后乃至大顺。", author: "老子", category: "玄德深矣"),
        Quote(text: "江海之所以能为百谷王者，以其善下之，故能为百谷王。", author: "老子", category: "江海百谷"),
        Quote(text: "是以圣人欲上民，必以言下之；欲先民，必以身后之。", author: "老子", category: "上民先民"),
        Quote(text: "是以圣人处上而民不重，处前而民不害。", author: "老子", category: "处上处前"),
        Quote(text: "是以天下乐推而不厌。", author: "老子", category: "乐推不厌"),
        Quote(text: "以其不争，故天下莫能与之争。", author: "老子", category: "不争莫能争"),
        Quote(text: "天下皆谓我道大，似不肖。", author: "老子", category: "道大不肖"),
        Quote(text: "夫唯大，故似不肖。若肖，久矣其细也夫！", author: "老子", category: "唯大不肖"),
        Quote(text: "我有三宝，持而保之。", author: "老子", category: "三宝"),
        Quote(text: "一曰慈，二曰俭，三曰不敢为天下先。", author: "老子", category: "慈俭不敢先"),
        Quote(text: "慈故能勇；俭故能广；不敢为天下先，故能成器长。", author: "老子", category: "慈勇俭广"),
        Quote(text: "今舍慈且勇，舍俭且广，舍后且先，死矣！", author: "老子", category: "舍慈俭"),
        Quote(text: "夫慈，以战则胜，以守则固。", author: "老子", category: "慈战守"),
        Quote(text: "天将救之，以慈卫之。", author: "老子", category: "以慈卫之"),
        Quote(text: "善为士者，不武；善战者，不怒。", author: "老子", category: "善士善战"),
        Quote(text: "善胜敌者，不与；善用人者，为之下。", author: "老子", category: "胜敌用人"),
        Quote(text: "是谓不争之德，是谓用人之力，是谓配天古之极。", author: "老子", category: "不争之德"),
        Quote(text: "用兵有言：吾不敢为主，而为客；不敢进寸，而退尺。", author: "老子", category: "用兵有言"),
        Quote(text: "是谓行无行，攘无臂，扔无敌，执无兵。", author: "老子", category: "行攘扔执"),
        Quote(text: "祸莫大于轻敌，轻敌几丧吾宝。", author: "老子", category: "祸莫轻敌"),
        Quote(text: "故抗兵相若，哀者胜矣。", author: "老子", category: "哀者胜矣"),
        Quote(text: "吾言甚易知，甚易行。", author: "老子", category: "甚易知"),
        Quote(text: "天下莫能知，莫能行。", author: "老子", category: "莫能知"),
        Quote(text: "言有宗，事有君。", author: "老子", category: "言有宗"),
        Quote(text: "夫唯无知，是以不我知。", author: "老子", category: "不我知"),
        Quote(text: "知我者希，则我者贵。", author: "老子", category: "知我者希"),
        Quote(text: "是以圣人被褐而怀玉。", author: "老子", category: "被褐怀玉"),
        Quote(text: "知不知，尚矣；不知知，病也。", author: "老子", category: "知不知"),
        Quote(text: "圣人不病，以其病病。夫唯病病，是以不病。", author: "老子", category: "不病病病"),
        Quote(text: "民不畏威，则大威至。", author: "老子", category: "不畏威"),
        Quote(text: "无狭其所居，无厌其所生。", author: "老子", category: "无狭无厌"),
        Quote(text: "夫唯不厌，是以不厌。", author: "老子", category: "唯不厌"),
        Quote(text: "是以圣人自知不自见，自爱不自贵。", author: "老子", category: "自知自爱"),
        Quote(text: "故去彼取此。", author: "老子", category: "去彼取此"),
        Quote(text: "勇于敢则杀，勇于不敢则活。", author: "老子", category: "勇于敢"),
        Quote(text: "此两者，或利或害。", author: "老子", category: "或利或害"),
        Quote(text: "天之所恶，孰知其故？", author: "老子", category: "天之所恶"),
        Quote(text: "是以圣人犹难之。", author: "老子", category: "犹难之"),
        Quote(text: "天之道，不争而善胜，不言而善应。", author: "老子", category: "天之道"),
        Quote(text: "不召而自来，繟然而善谋。", author: "老子", category: "不召自来"),
        Quote(text: "天网恢恢，疏而不失。", author: "老子", category: "天网恢恢"),
        Quote(text: "民不畏死，奈何以死惧之？", author: "老子", category: "不畏死"),
        Quote(text: "若使民常畏死，而为奇者，吾得执而杀之，孰敢？", author: "老子", category: "畏死"),
        Quote(text: "常有司杀者杀。夫代司杀者杀，是谓代大匠斫。", author: "老子", category: "司杀者"),
        Quote(text: "夫代大匠斫者，希有不伤其手矣。", author: "老子", category: "代大匠斫"),
        Quote(text: "民之饥，以其上食税之多，是以饥。", author: "老子", category: "民之饥"),
        Quote(text: "民之难治，以其上之有为，是以难治。", author: "老子", category: "民难治"),
        Quote(text: "民之轻死，以其上求生之厚，是以轻死。", author: "老子", category: "民轻死"),
        Quote(text: "夫唯无以生为者，是贤于贵生。", author: "老子", category: "无以生为"),
        Quote(text: "人之生也柔弱，其死也坚强。", author: "老子", category: "生柔弱"),
        Quote(text: "万物草木之生也柔脆，其死也枯槁。", author: "老子", category: "柔脆枯槁"),
        Quote(text: "故坚强者死之徒，柔弱者生之徒。", author: "老子", category: "坚强柔弱"),
        Quote(text: "是以兵强则灭，木强则折。", author: "老子", category: "兵强木强"),
        Quote(text: "强大处下，柔弱处上。", author: "老子", category: "强大处下"),
        Quote(text: "天之道，其犹张弓与？", author: "老子", category: "天之道张弓"),
        Quote(text: "高者抑之，下者举之；有余者损之，不足者补之。", author: "老子", category: "高下有余不足"),
        Quote(text: "天之道，损有余而补不足。", author: "老子", category: "损有余补不足"),
        Quote(text: "人之道，则不然，损不足以奉有余。", author: "老子", category: "损不足奉有余"),
        Quote(text: "孰能有余以奉天下？唯有道者。", author: "老子", category: "有道者"),
        Quote(text: "是以圣人为而不恃，功成而不处，其不欲见贤。", author: "老子", category: "为而不恃"),
        Quote(text: "天下莫柔弱于水，而攻坚强者莫之能胜，以其无以易之。", author: "老子", category: "莫柔弱于水"),
        Quote(text: "弱之胜强，柔之胜刚，天下莫不知，莫能行。", author: "老子", category: "弱胜强"),
        Quote(text: "是以圣人云：受国之垢，是谓社稷主。", author: "老子", category: "受国之垢"),
        Quote(text: "受国不祥，是为天下王。", author: "老子", category: "受国不祥"),
        Quote(text: "正言若反。", author: "老子", category: "正言若反"),
        Quote(text: "和大怨，必有余怨；报怨以德，安可以为善？", author: "老子", category: "和大怨"),
        Quote(text: "是以圣人执左契，而不责于人。", author: "老子", category: "执左契"),
        Quote(text: "有德司契，无德司彻。", author: "老子", category: "司契司彻"),
        Quote(text: "天道无亲，常与善人。", author: "老子", category: "天道无亲"),
        Quote(text: "小国寡民。", author: "老子", category: "小国寡民"),
        Quote(text: "使有什伯之器而不用；使民重死而不远徙。", author: "老子", category: "什伯之器"),
        Quote(text: "虽有舟舆，无所乘之；虽有甲兵，无所陈之。", author: "老子", category: "舟舆甲兵"),
        Quote(text: "使人复结绳而用之。", author: "老子", category: "结绳而用"),
        Quote(text: "甘其食，美其服，安其居，乐其俗。", author: "老子", category: "甘美安乐"),
        Quote(text: "邻国相望，鸡犬之声相闻，民至老死，不相往来。", author: "老子", category: "邻国相望"),
        Quote(text: "信言不美，美言不信。", author: "老子", category: "信言美言"),
        Quote(text: "善者不辩，辩者不善。", author: "老子", category: "善者辩者"),
        Quote(text: "知者不博，博者不知。", author: "老子", category: "知者博者"),
        Quote(text: "圣人不积，既以为人己愈有，既以与人己愈多。", author: "老子", category: "圣人不积"),
        Quote(text: "天之道，利而不害；圣人之道，为而不争。", author: "老子", category: "利而不害"),
    ]
    
