        Quote(text: "人生没有白走的路，每一步都算数。", author: "佚名", category: "心态建设"),
        Quote(text: "低谷期不是终点，而是蓄力的开始。", author: "佚名", category: "心态建设"),
        Quote(text: "你对自己说的话，决定了你的情绪。", author: "佚名", category: "心态建设"),
        Quote(text: "接纳焦虑，然后带着焦虑继续前行。", author: "佚名", category: "心态建设"),
        Quote(text: "不是所有事都需要有意义，有些事做了就是意义。", author: "佚名", category: "心态建设"),
        Quote(text: "真正的成熟，是能在不确定性中保持从容。", author: "佚名", category: "心态建设"),
        Quote(text: "不要让昨天的情绪，毁了今天的心情。", author: "佚名", category: "心态建设"),
        Quote(text: "你的压力，大多来自对未来的过度想象。", author: "佚名", category: "心态建设"),
        Quote(text: "学会与不确定性共处，是成年人的必修课。", author: "佚名", category: "心态建设"),
        Quote(text: "抱怨不会改变现实，行动才会。", author: "佚名", category: "心态建设"),
        Quote(text: "你关注的焦点，决定了你的情绪状态。", author: "佚名", category: "心态建设"),
        Quote(text: "允许自己偶尔脆弱，但不要沉溺于脆弱。", author: "佚名", category: "心态建设"),
        Quote(text: "内心的平静，比外在的成功更重要。", author: "佚名", category: "心态建设"),
        Quote(text: "你不需要所有人都喜欢你，你只需要做对的事。", author: "佚名", category: "心态建设"),
        Quote(text: "生活的意义不是找到的，而是创造的。", author: "佚名", category: "心态建设"),
        Quote(text: "幸福不是拥有得多，而是计较得少。", author: "佚名", category: "心态建设"),
        Quote(text: "与其内耗，不如行动。", author: "佚名", category: "心态建设"),
        Quote(text: "你的人生不需要向任何人解释。", author: "佚名", category: "心态建设"),
        Quote(text: "接受平凡，但不要甘于平庸。", author: "佚名", category: "心态建设"),
        Quote(text: "情绪来了就来了，不必抗拒，但也别被它牵着走。", author: "佚名", category: "心态建设"),
        Quote(text: "所有的焦虑，都可以用行动来缓解。", author: "佚名", category: "心态建设"),

        // 梦想与现实
        Quote(text: "梦想不会逃跑，逃跑的总是自己。", author: "佚名", category: "梦想与现实"),
        Quote(text: "理想很丰满，现实很骨感，但骨架上会长出肉来。", author: "佚名", category: "梦想与现实"),
        Quote(text: "不是现实支撑了梦想，而是梦想照亮了现实。", author: "佚名", category: "梦想与现实"),
        Quote(text: "梦想不需要太大，只需要足够让你心动。", author: "佚名", category: "梦想与现实"),
        Quote(text: "世界上最远的距离，是从想到到做到。", author: "佚名", category: "梦想与现实"),
        Quote(text: "梦想不是用来实现的，是用来指引方向的。", author: "佚名", category: "梦想与现实"),
        Quote(text: "你以为的遥不可及，可能只是缺少一个开始。", author: "佚名", category: "梦想与现实"),
        Quote(text: "与其仰望别人的梦想，不如脚踏实地走自己的路。", author: "佚名", category: "梦想与现实"),
        Quote(text: "梦想和现实之间的桥梁，叫做行动。", author: "佚名", category: "梦想与现实"),
        Quote(text: "不是所有的种子都能开花，但不播种一定不会有收获。", author: "佚名", category: "梦想与现实"),
        Quote(text: "梦想不怕晚，只怕你从未开始。", author: "佚名", category: "梦想与现实"),
        Quote(text: "现实会磨平棱角，但不要让它磨灭光芒。", author: "佚名", category: "梦想与现实"),
        Quote(text: "把大梦想拆成小目标，每天靠近一点点。", author: "佚名", category: "梦想与现实"),
        Quote(text: "追梦的路上注定孤独，但风景也注定独特。", author: "佚名", category: "梦想与现实"),
        Quote(text: "梦想不是空想，是想了就去做。", author: "佚名", category: "梦想与现实"),
        Quote(text: "即使梦想遥不可及，也要在追逐中成为更好的自己。", author: "佚名", category: "梦想与现实"),
        Quote(text: "不要因为走得太远，而忘了为什么出发。", author: "佚名", category: "梦想与现实"),
        Quote(text: "梦想的保质期，取决于你的行动力。", author: "佚名", category: "梦想与现实"),
        Quote(text: "现实是梦想的试金石，不是墓志铭。", author: "佚名", category: "梦想与现实"),
        Quote(text: "每一个实现梦想的人，都曾是别人眼中的疯子。", author: "佚名", category: "梦想与现实"),

        // 生活哲学
        Quote(text: "生活不是等待暴风雨过去，而是学会在雨中起舞。", author: "佚名", category: "生活哲学"),
        Quote(text: "简单不是简陋，而是去掉多余后的精华。", author: "佚名", category: "生活哲学"),
        Quote(text: "人生就像一杯咖啡，苦是本质，甜是选择。", author: "佚名", category: "生活哲学"),
        Quote(text: "活着本身就是一种勇气。", author: "佚名", category: "生活哲学"),
        Quote(text: "生活给你柠檬，就把它做成柠檬水。", author: "佚名", category: "生活哲学"),
        Quote(text: "人生没有标准答案，只有自己的答案。", author: "佚名", category: "生活哲学"),
        Quote(text: "把每一天都当作第一天来过，保持新鲜感。", author: "佚名", category: "生活哲学"),
        Quote(text: "把每一天都当作最后一天来过，保持紧迫感。", author: "佚名", category: "生活哲学"),
        Quote(text: "生活的艺术，在于找到忙碌与悠闲的平衡。", author: "佚名", category: "生活哲学"),
        Quote(text: "人生最大的遗憾，不是做过什么，而是没做什么。", author: "佚名", category: "生活哲学"),
        Quote(text: "快乐不是因为拥有得多，而是计较得少。", author: "佚名", category: "生活哲学"),
        Quote(text: "生活的质感，藏在那些看似无用的细节里。", author: "佚名", category: "生活哲学"),
        Quote(text: "人生如茶，不会苦一辈子，但总会苦一阵子。", author: "佚名", category: "生活哲学"),
        Quote(text: "最深的哲理，往往藏在最简单的生活里。", author: "佚名", category: "生活哲学"),
        Quote(text: "生活不需要太多道理，过好当下就是真理。", author: "佚名", category: "生活哲学"),
        Quote(text: "人生最好的状态，是眼里有光，心中有爱，脚下有路。", author: "佚名", category: "生活哲学"),
        Quote(text: "把复杂的事情做简单，是智慧；把简单的事情做极致，是境界。", author: "佚名", category: "生活哲学"),
        Quote(text: "生活的意义在于过程，而非结果。", author: "佚名", category: "生活哲学"),
        Quote(text: "人生的风景，不在终点，在路上。", author: "佚名", category: "生活哲学"),
        Quote(text: "最好的生活状态：物质极简，灵魂丰盈。", author: "佚名", category: "生活哲学"),
        Quote(text: "人生不是轨道，而是旷野。", author: "佚名", category: "生活哲学"),
        Quote(text: "允许一切发生，然后从中成长。", author: "佚名", category: "生活哲学"),
        Quote(text: "人生就像骑自行车，想要保持平衡就得不断前进。", author: "佚名", category: "生活哲学"),
        Quote(text: "生活的真相是：没有完美，只有完整。", author: "佚名", category: "生活哲学"),
        Quote(text: "把生活过成诗，不一定要远方，用心就好。", author: "佚名", category: "生活哲学"),

        // 人际关系
        Quote(text: "真正的朋友，不是锦上添花，而是雪中送炭。", author: "佚名", category: "人际关系"),
        Quote(text: "圈子不同，不必强融。", author: "佚名", category: "人际关系"),
        Quote(text: "人际关系的本质，是价值交换。", author: "佚名", category: "人际关系"),
        Quote(text: "学会独处，是建立健康关系的前提。", author: "佚名", category: "人际关系"),
        Quote(text: "不要试图改变别人，先做好自己。", author: "佚名", category: "人际关系"),
        Quote(text: "最舒服的关系，是相处不累。", author: "佚名", category: "人际关系"),
        Quote(text: "你的层次，决定了你的圈子。", author: "佚名", category: "人际关系"),
        Quote(text: "远离消耗你的人，靠近滋养你的人。", author: "佚名", category: "人际关系"),
        Quote(text: "人际交往最大的误区，是把客气当亲密。", author: "佚名", category: "人际关系"),
        Quote(text: "真正的成熟，是能和不同的人和谐相处。", author: "佚名", category: "人际关系"),
        Quote(text: "不必讨好所有人，你只需要对的人。", author: "佚名", category: "人际关系"),
        Quote(text: "社交的本质不是认识多少人，而是被多少人需要。", author: "佚名", category: "人际关系"),
        Quote(text: "好的关系是互相成就，坏的关系是互相消耗。", author: "佚名", category: "人际关系"),
        Quote(text: "学会倾听，比学会说话更重要。", author: "佚名", category: "人际关系"),
        Quote(text: "在关系中保持边界感，是对彼此最大的尊重。", author: "佚名", category: "人际关系"),
        Quote(text: "不要在朋友圈里找存在感，在真实生活里找价值感。", author: "佚名", category: "人际关系"),
        Quote(text: "能说到一起的人，自然会走到一起。", author: "佚名", category: "人际关系"),
        Quote(text: "与其改变别人，不如改变自己对别人的期待。", author: "佚名", category: "人际关系"),
        Quote(text: "人际关系的质量，比数量重要得多。", author: "佚名", category: "人际关系"),
        Quote(text: "真诚是最高级的社交技巧。", author: "佚名", category: "人际关系"),

        // 坚持与韧性
        Quote(text: "坚持不是看到了希望才努力，而是努力了才看到希望。", author: "佚名", category: "坚持与韧性"),
        Quote(text: "放弃很容易，坚持很难，但值得的事从来不简单。", author: "佚名", category: "坚持与韧性"),
        Quote(text: "所谓的天赋，不过是热爱的另一个名字。", author: "佚名", category: "坚持与韧性"),
        Quote(text: "每一次想放弃的时候，都是在考验你的决心。", author: "佚名", category: "坚持与韧性"),
        Quote(text: "竹子用了四年只长了三厘米，第五年开始每天长三十厘米。", author: "佚名", category: "坚持与韧性"),
        Quote(text: "不是所有的坚持都有结果，但总有一些坚持能从冰封的土地里绽放花朵。", author: "佚名", category: "坚持与韧性"),
        Quote(text: "复利的威力在于：前期看不到效果，后期指数爆发。", author: "佚名", category: "坚持与韧性"),
        Quote(text: "你今天的坚持，是明天的底气。", author: "佚名", category: "坚持与韧性"),
        Quote(text: "慢一点没关系，重要的是不要停下来。", author: "佚名", category: "坚持与韧性"),
        Quote(text: "坚持的本质，是在看不到结果时依然选择相信。", author: "佚名", category: "坚持与韧性"),
        Quote(text: "世界上最可怕的事，是一辈子都在后悔没有坚持。", author: "佚名", category: "坚持与韧性"),
        Quote(text: "韧性不是硬撑，而是跌倒后还能爬起来的能力。", author: "佚名", category: "坚持与韧性"),
        Quote(text: "黎明前总是最黑暗的，但太阳总会升起。", author: "佚名", category: "坚持与韧性"),
        Quote(text: "坚持做正确的事，时间会给你答案。", author: "佚名", category: "坚持与韧性"),
        Quote(text: "所谓的运气，不过是坚持的另一个名字。", author: "佚名", category: "坚持与韧性"),
        Quote(text: "不积跬步无以至千里，不积小流无以成江海。", author: "荀子", category: "坚持与韧性"),
        Quote(text: "你只需要比昨天的自己好一点点就够了。", author: "佚名", category: "坚持与韧性"),
        Quote(text: "所有的伟大，都源于一个勇敢的开始和漫长的坚持。", author: "佚名", category: "坚持与韧性"),
        Quote(text: "坚持不是咬牙切齿，而是平静地重复。", author: "佚名", category: "坚持与韧性"),
        Quote(text: "时间不会辜负每一个认真生活的人。", author: "佚名", category: "坚持与韧性"),

        // 勇气与改变
        Quote(text: "改变很痛，但不改变更痛。", author: "佚名", category: "勇气与改变"),
        Quote(text: "人生最大的风险，是从不冒险。", author: "佚名", category: "勇气与改变"),
        Quote(text: "勇气不是不害怕，而是害怕了依然选择前行。", author: "佚名", category: "勇气与改变"),
        Quote(text: "走出去，世界就在眼前；走不出去，眼前就是世界。", author: "佚名", category: "勇气与改变"),
        Quote(text: "舒适区很舒服，但那里没有成长。", author: "佚名", category: "勇气与改变"),
        Quote(text: "所有的改变都从不舒服开始。", author: "佚名", category: "勇气与改变"),
        Quote(text: "不要等所有条件都成熟了才行动，那时候机会已经不在了。", author: "佚名", category: "勇气与改变"),
        Quote(text: "人生没有白走的路，但有很多不敢走的路。", author: "佚名", category: "勇气与改变"),
        Quote(text: "最大的遗憾不是失败，而是我本可以。", author: "佚名", category: "勇气与改变"),
        Quote(text: "勇敢不是没有恐惧，而是带着恐惧依然前行。", author: "佚名", category: "勇气与改变"),
        Quote(text: "与其后悔没做，不如做了再后悔。", author: "佚名", category: "勇气与改变"),
        Quote(text: "人生最重要的不是所处位置，而是所朝方向。", author: "佚名", category: "勇气与改变"),
        Quote(text: "每一次改变，都是给自己一次重生的机会。", author: "佚名", category: "勇气与改变"),
        Quote(text: "不要害怕重新开始，这次你不是从零开始，而是从经验开始。", author: "佚名", category: "勇气与改变"),
        Quote(text: "人生最大的勇气，是承认错误并重新出发。", author: "佚名", category: "勇气与改变"),
        Quote(text: "改变世界很难，改变自己更难，但后者更有效。", author: "佚名", category: "勇气与改变"),
        Quote(text: "迈出第一步，你就已经超过了百分之九十的人。", author: "佚名", category: "勇气与改变"),
        Quote(text: "如果你不敢失败，你就永远无法成功。", author: "佚名", category: "勇气与改变"),
        Quote(text: "生命的精彩在于不确定性，而非按部就班。", author: "佚名", category: "勇气与改变"),
        Quote(text: "做你害怕做的事，然后你会发现不过如此。", author: "佚名", category: "勇气与改变"),

        // 专注与极简
        Quote(text: "少即是多，慢即是快。", author: "佚名", category: "专注与极简"),
        Quote(text: "断舍离不是扔东西，而是理清什么才是重要的。", author: "佚名", category: "专注与极简"),
        Quote(text: "专注是这个时代最稀缺的能力。", author: "佚名", category: "专注与极简"),
        Quote(text: "把一件事做到极致，胜过把一百件事做到平庸。", author: "佚名", category: "专注与极简"),
        Quote(text: "极简不是缺少，而是精准。", author: "佚名", category: "专注与极简"),
        Quote(text: "你的注意力是你最宝贵的资产，不要随意挥霍。", author: "佚名", category: "专注与极简"),
        Quote(text: "减少选择，增加行动。", author: "佚名", category: "专注与极简"),
        Quote(text: "真正的专注，是在嘈杂中保持内心的安静。", author: "佚名", category: "专注与极简"),
        Quote(text: "删掉不需要的App，退出不需要的群，生活立刻清爽。", author: "佚名", category: "专注与极简"),
        Quote(text: "一次只做一件事，是最高效的工作方式。", author: "佚名", category: "专注与极简"),
        Quote(text: "极简生活的核心不是少，而是够。", author: "佚名", category: "专注与极简"),
        Quote(text: "把手机调成静音，把人生调成专注。", author: "佚名", category: "专注与极简"),
        Quote(text: "你拥有的越多，被占有的也越多。", author: "佚名", category: "专注与极简"),
        Quote(text: "减法生活，加法成长。", author: "佚名", category: "专注与极简"),
        Quote(text: "清理房间就是清理内心。", author: "佚名", category: "专注与极简"),
        Quote(text: "信息过载时代，过滤信息比获取信息更重要。", author: "佚名", category: "专注与极简"),
        Quote(text: "把精力集中在少数重要的事情上，是成功者的共同习惯。", author: "佚名", category: "专注与极简"),
        Quote(text: "简单的事情重复做，你就是专家。", author: "佚名", category: "专注与极简"),
        Quote(text: "少关注别人的生活，多经营自己的人生。", author: "佚名", category: "专注与极简"),
        Quote(text: "心静了，世界就清晰了。", author: "佚名", category: "专注与极简"),

        // 感恩与幸福
        Quote(text: "感恩不是一种礼貌，而是一种生活态度。", author: "佚名", category: "感恩与幸福"),
        Quote(text: "幸福不是得到你想要的，而是珍惜你拥有的。", author: "佚名", category: "感恩与幸福"),
        Quote(text: "每天记录三件感恩的事，幸福感会显著提升。", author: "佚名", category: "感恩与幸福"),
        Quote(text: "比较是痛苦的根源，感恩是快乐的起点。", author: "佚名", category: "感恩与幸福"),
        Quote(text: "你拥有的健康，是别人奢望的明天。", author: "佚名", category: "感恩与幸福"),
        Quote(text: "幸福很简单：健康的身体，温暖的家，三五知己。", author: "佚名", category: "感恩与幸福"),
        Quote(text: "懂得感恩的人，运气都不会太差。", author: "佚名", category: "感恩与幸福"),
        Quote(text: "生活中最美好的东西，都是免费的：阳光、空气和爱。", author: "佚名", category: "感恩与幸福"),
        Quote(text: "幸福不在远方，在当下的每一个瞬间。", author: "佚名", category: "感恩与幸福"),
        Quote(text: "心存感激，所遇皆温柔。", author: "佚名", category: "感恩与幸福"),
        Quote(text: "你抱怨的今天，是昨天逝去的人渴望的明天。", author: "佚名", category: "感恩与幸福"),
        Quote(text: "感恩让平凡的日子闪闪发光。", author: "佚名", category: "感恩与幸福"),
        Quote(text: "幸福不是拥有全世界，而是在平凡中找到欢喜。", author: "佚名", category: "感恩与幸福"),
        Quote(text: "每天醒来，感谢又是一个崭新的开始。", author: "佚名", category: "感恩与幸福"),
        Quote(text: "真正的富足，不是拥有更多，而是需要更少。", author: "佚名", category: "感恩与幸福"),
        Quote(text: "对生活保持敬畏，对拥有保持感恩。", author: "佚名", category: "感恩与幸福"),
        Quote(text: "能吃能睡能笑，就是人生最大的幸福。", author: "佚名", category: "感恩与幸福"),
        Quote(text: "珍惜当下，因为当下终将成为回忆。", author: "佚名", category: "感恩与幸福"),
        Quote(text: "感恩生命中出现的每一个人，他们都是来渡你的。", author: "佚名", category: "感恩与幸福"),
        Quote(text: "平凡的日子因为感恩而变得不平凡。", author: "佚名", category: "感恩与幸福"),

        // 现代智慧
        Quote(text: "数据会说话，但要学会听懂它在说什么。", author: "佚名", category: "现代智慧"),
        Quote(text: "人工智能不会取代你，但会用人工智能的人会。", author: "佚名", category: "现代智慧"),
        Quote(text: "在这个时代，不学习就是退步。", author: "佚名", category: "现代智慧"),
        Quote(text: "信息差就是财富差。", author: "佚名", category: "现代智慧"),
        Quote(text: "工具是中性的，关键在于使用它的人。", author: "佚名", category: "现代智慧"),
        Quote(text: "未来的文盲不是不识字的人，而是不会学习的人。", author: "佚名", category: "现代智慧"),
        Quote(text: "技术改变生活，但人性从未改变。", author: "佚名", category: "现代智慧"),
        Quote(text: "拥抱变化，因为变化是唯一不变的东西。", author: "佚名", category: "现代智慧"),
        Quote(text: "在信息爆炸的时代，深度思考能力比记忆力更值钱。", author: "佚名", category: "现代智慧"),
        Quote(text: "不要让算法决定你的思想。", author: "佚名", category: "现代智慧"),
        Quote(text: "未来属于那些既能仰望星空又能脚踏实地的人。", author: "佚名", category: "现代智慧"),
        Quote(text: "连接比拥有更重要，在数字时代尤其如此。", author: "佚名", category: "现代智慧"),
        Quote(text: "每一次技术革命，都在淘汰不肯学习的人。", author: "佚名", category: "现代智慧"),
        Quote(text: "在这个时代，个人品牌就是你的数字资产。", author: "佚名", category: "现代智慧"),
        Quote(text: "线上线下不是对立，而是互补。", author: "佚名", category: "现代智慧"),
        Quote(text: "数据驱动决策，直觉驱动创新。", author: "佚名", category: "现代智慧"),
        Quote(text: "不要做技术的奴隶，要做技术的主人。", author: "佚名", category: "现代智慧"),
        Quote(text: "在快速变化的时代，慢思考反而成了稀缺能力。", author: "佚名", category: "现代智慧"),
        Quote(text: "终身学习者永远年轻。", author: "佚名", category: "现代智慧"),
        Quote(text: "未来已来，只是分布不均。", author: "威廉·吉布森", category: "现代智慧"),

        // 行动与执行
        Quote(text: "想，全是问题；做，全是答案。", author: "佚名", category: "行动与执行"),
        Quote(text: "完成比完美更重要。", author: "佚名", category: "行动与执行"),
        Quote(text: "行动是治愈焦虑的良药。", author: "佚名", category: "行动与执行"),
        Quote(text: "不要等到万事俱备，先开始了再说。", author: "佚名", category: "行动与执行"),
        Quote(text: "最好的计划，不如最差的行动。", author: "佚名", category: "行动与执行"),
        Quote(text: "你不需要很厉害才能开始，但你需要开始才能很厉害。", author: "佚名", category: "行动与执行"),
        Quote(text: "百分之九十的失败，都败在没有开始。", author: "佚名", category: "行动与执行"),
        Quote(text: "种一棵树最好的时间是十年前，其次是现在。", author: "佚名", category: "行动与执行"),
        Quote(text: "不要用思考代替行动，思考再多也不如迈出一步。", author: "佚名", category: "行动与执行"),
        Quote(text: "执行力是拉开人与人差距的关键。", author: "佚名", category: "行动与执行"),
        Quote(text: "再好的想法不执行等于零。", author: "佚名", category: "行动与执行"),
        Quote(text: "做了可能后悔一阵子，不做会后悔一辈子。", author: "佚名", category: "行动与执行"),
        Quote(text: "行动不一定带来成功，但不行动一定不会成功。", author: "佚名", category: "行动与执行"),
        Quote(text: "先把事情做对，再把事情做好。", author: "佚名", category: "行动与执行"),
        Quote(text: "小步快跑，快速迭代，是互联网时代的行动哲学。", author: "佚名", category: "行动与执行"),
        Quote(text: "不要让完美主义成为拖延的借口。", author: "佚名", category: "行动与执行"),
        Quote(text: "今天就是行动的最好日子。", author: "佚名", category: "行动与执行"),
        Quote(text: "与其花时间纠结，不如花时间行动。", author: "佚名", category: "行动与执行"),
        Quote(text: "从五分钟开始行动，你会发现停不下来。", author: "佚名", category: "行动与执行"),
        Quote(text: "真正的改变发生在行动中，而非计划里。", author: "佚名", category: "行动与执行"),

        // 独处与内省
        Quote(text: "独处不是孤独，而是和自己对话的最好时光。", author: "佚名", category: "独处与内省"),
        Quote(text: "一个人最好的状态，是在独处时感到充实。", author: "佚名", category: "独处与内省"),
        Quote(text: "所有的顿悟，都发生在独处的时刻。", author: "佚名", category: "独处与内省"),
        Quote(text: "学会和自己相处，是一辈子的功课。", author: "佚名", category: "独处与内省"),
        Quote(text: "独处是灵魂的充电站。", author: "佚名", category: "独处与内省"),
        Quote(text: "在独处中认识自己，在人群中忘记自己。", author: "佚名", category: "独处与内省"),
        Quote(text: "最深的思考，总在深夜独处时完成。", author: "佚名", category: "独处与内省"),
        Quote(text: "一个人逛街、吃饭、看电影，也是一种能力。", author: "佚名", category: "独处与内省"),
        Quote(text: "独处让你不必取悦任何人。", author: "佚名", category: "独处与内省"),
        Quote(text: "在安静中，你才能听见内心的声音。", author: "佚名", category: "独处与内省"),
        Quote(text: "独处是创造力的温床。", author: "佚名", category: "独处与内省"),
        Quote(text: "享受独处的人，内心一定很丰盈。", author: "佚名", category: "独处与内省"),
        Quote(text: "每天给自己半小时独处时间，什么都不做也可以。", author: "佚名", category: "独处与内省"),
        Quote(text: "你和自己相处的方式，决定了你和世界相处的方式。", author: "佚名", category: "独处与内省"),
        Quote(text: "独处不是逃避世界，而是回归自己。", author: "佚名", category: "独处与内省"),
        Quote(text: "静坐常思己过，闲谈莫论人非。", author: "佚名", category: "独处与内省"),
        Quote(text: "在独处中整理思绪，在喧嚣中保持清醒。", author: "佚名", category: "独处与内省"),
        Quote(text: "一个人只有学会独处，才能真正享受陪伴。", author: "佚名", category: "独处与内省"),
        Quote(text: "最了解你的人，应该是你自己。", author: "佚名", category: "独处与内省"),
        Quote(text: "和自己和解，是人生最重要的一课。", author: "佚名", category: "独处与内省"),
    ]

