        Quote(text: "真正的创新，是发自内心的热爱。", author: "Trigin", category: "自信与成长", translation: "True innovation comes from inner passion."),
        Quote(text: "创新的路上，你并不孤单。", author: "佚名", category: "自信与成长", translation: "On the road of innovation, you are not alone."),
