        Quote(text: "用自由对抗焦虑，用行动治愈迷茫。", author: "佚名", category: "勇气与坚持", translation: "Use freedom to fight anxiety and action to cure confusion."),
        Quote(text: "自由不是别人的事，是你自己的事。", author: "古语", category: "勇气与坚持", translation: "freedom is not others' business; it is your own."),
        Quote(text: "自由是一种能力，需要刻意练习。", author: "佚名", category: "勇气与坚持", translation: "freedom is an ability that needs deliberate practice."),
        Quote(text: "自由让你看清自己，也看清世界。", author: "谚语", category: "勇气与坚持", translation: "freedom lets you see yourself and the world clearly."),
        Quote(text: "把自由当作一种生活方式。", author: "谚语", category: "勇气与坚持", translation: "Make freedom a way of life."),
        Quote(text: "自由是最好的老师，实践是最好的课堂。", author: "佚名", category: "勇气与坚持", translation: "freedom is the best teacher; practice is the best classroom."),
        Quote(text: "自由让平凡的日子闪闪发光。", author: "古语", category: "勇气与坚持", translation: "freedom makes ordinary days shine."),
        Quote(text: "自由不分年龄，什么时候开始都不晚。", author: "Trigin", category: "勇气与坚持", translation: "freedom knows no age; it is never too late to start."),
        Quote(text: "自由的深度，决定人生的高度。", author: "佚名", category: "勇气与坚持", translation: "The depth of freedom determines the height of life."),
        Quote(text: "自由是通向自由的桥梁。", author: "谚语", category: "勇气与坚持", translation: "freedom is the bridge to freedom."),
        Quote(text: "自由不是为了取悦别人，而是为了自己。", author: "古语", category: "勇气与坚持", translation: "freedom is not to please others, but for yourself."),
        Quote(text: "天行健，君子以自强不息。", author: "《周易》", category: "自强与奋斗", translation: "As heaven maintains vigor, a gentleman ceaselessly strives for self-improvement."),
        Quote(text: "地势坤，君子以厚德载物。", author: "《周易》", category: "责任与担当", translation: "As earth is receptive, a gentleman carries virtue to bear all things."),
        Quote(text: "穷则变，变则通，通则久。", author: "《周易》", category: "创新与突破", translation: "When in poverty, change; when changed, unblock; when unblocked, endure."),
        Quote(text: "满招损，谦受益。", author: "《尚书》", category: "自信与成长", translation: "Pride brings loss; humility brings benefit."),
        Quote(text: "皮之不存，毛将焉附。", author: "《左传》", category: "人生智慧", translation: "If the skin does not exist, where can the hair attach?"),
        Quote(text: "居安思危，思则有备，有备无患。", author: "《左传》", category: "梦想与目标", translation: "In safety think of danger; thinking leads to preparation; preparation prevents disaster."),
        Quote(text: "人谁无过？过而能改，善莫大焉。", author: "《左传》", category: "自信与成长", translation: "Who makes no mistakes? To err and reform is the greatest good."),
        Quote(text: "辅车相依，唇亡齿寒。", author: "《左传》", category: "人际关系", translation: "The cheek and teeth depend on each other; if lips are gone, teeth will be cold."),
        Quote(text: "多行不义必自毙。", author: "《左传》", category: "责任与担当", translation: "Doing much unrighteousness will lead to self-destruction."),
        Quote(text: "欲加之罪，何患无辞。", author: "《左传》", category: "人生智慧", translation: "If you want to charge someone, you can always find a pretext."),
        Quote(text: "风萧萧兮易水寒，壮士一去兮不复还。", author: "荆轲", category: "勇气与坚持", translation: "The wind whistles, the Yi River is cold; the brave man departs, never to return."),
        Quote(text: "力拔山兮气盖世，时不利兮骓不逝。", author: "项羽", category: "失败与挫折", translation: "Strength to uproot mountains, spirit covering the world; but the times are unfavorable, my steed will not pass."),
        Quote(text: "大风起兮云飞扬，威加海内兮归故乡。", author: "刘邦", category: "梦想与目标", translation: "The great wind rises, clouds fly; might spreads within the seas, returning to my hometown."),
        Quote(text: "少壮不努力，老大徒伤悲。", author: "《长歌行》", category: "时间与效率", translation: "If one does not work hard in youth, one will regret it in old age."),
        Quote(text: "百川东到海，何时复西归？", author: "《长歌行》", category: "时间与效率", translation: "All rivers flow east to the sea; when will they return west?"),
        Quote(text: "山不在高，有仙则名。水不在深，有龙则灵。", author: "刘禹锡", category: "人生智慧", translation: "A mountain need not be high; it is famous if immortals dwell. Water need not be deep; it is spiritual if dragons dwell."),
        Quote(text: "斯是陋室，惟吾德馨。", author: "刘禹锡", category: "幸福与满足", translation: "This is a humble room, but my virtue makes it fragrant."),
        Quote(text: "谈笑有鸿儒，往来无白丁。", author: "刘禹锡", category: "人际关系", translation: "In conversation are great scholars; in coming and going no illiterates."),
        Quote(text: "无丝竹之乱耳，无案牍之劳形。", author: "刘禹锡", category: "健康与生活", translation: "No string and bamboo to confuse the ear, no documents to tire the body."),
        Quote(text: "南阳诸葛庐，西蜀子云亭。孔子云：何陋之有？", author: "刘禹锡", category: "幸福与满足", translation: "Zhuge's hut in Nanyang, Ziyun's pavilion in Western Shu. Confucius said: what is humble about it?"),
        Quote(text: "慈母手中线，游子身上衣。", author: "孟郊", category: "家庭与亲情", translation: "In the loving mother's hands threads; on the wandering son's body clothes."),
        Quote(text: "临行密密缝，意恐迟迟归。", author: "孟郊", category: "家庭与亲情", translation: "Before departure she sews closely, fearing his late return."),
        Quote(text: "谁言寸草心，报得三春晖。", author: "孟郊", category: "家庭与亲情", translation: "Who says the heart of an inch-long grass can repay the spring sunshine of three months?"),
        Quote(text: "春风得意马蹄疾，一日看尽长安花。", author: "孟郊", category: "幸福与满足", translation: "The spring breeze is proud, the horse's hooves are swift; in one day seeing all the flowers of Chang'an."),
        Quote(text: "昔日龌龊不足夸，今朝放荡思无涯。", author: "孟郊", category: "自信与成长", translation: "Former squalor is not worth boasting; today's freedom knows no bounds."),
        Quote(text: "少年心事当拏云，谁念幽寒坐呜呃。", author: "李贺", category: "梦想与目标", translation: "A youth's heart should reach the clouds; who pities the cold and weeping?"),
        Quote(text: "黑云压城城欲摧，甲光向日金鳞开。", author: "李贺", category: "勇气与坚持", translation: "Black clouds press the city, the city seems to fall; armor gleams in the sun like golden scales."),
        Quote(text: "角声满天秋色里，塞上燕脂凝夜紫。", author: "李贺", category: "勇气与坚持", translation: "Horn sounds fill the autumn sky; frontier rouge congeals into night purple."),
        Quote(text: "半卷红旗临易水，霜重鼓寒声不起。", author: "李贺", category: "勇气与坚持", translation: "Half-rolled red flag by the Yi River; heavy frost, cold drums, sound cannot rise."),
        Quote(text: "报君黄金台上意，提携玉龙为君死。", author: "李贺", category: "责任与担当", translation: "Repaying the lord's favor from the Golden Terrace, I will die for him with the jade dragon sword."),
        Quote(text: "大漠沙如雪，燕山月似钩。", author: "李贺", category: "人生智慧", translation: "The desert sand is like snow; the Yan Mountain moon like a hook."),
        Quote(text: "何当金络脑，快走踏清秋。", author: "李贺", category: "梦想与目标", translation: "When will I have a golden bridle? Galloping through the clear autumn."),
        Quote(text: "男儿何不带吴钩，收取关山五十州。", author: "李贺", category: "梦想与目标", translation: "Why don't men carry Wu hooks, recovering the fifty states of Guanshan?"),
        Quote(text: "请君暂上凌烟阁，若个书生万户侯。", author: "李贺", category: "梦想与目标", translation: "Please ascend the Lingyan Pavilion for a while; which scholar has ever become a marquis of ten thousand households?"),
        Quote(text: "寻寻觅觅，冷冷清清，凄凄惨惨戚戚。", author: "李清照", category: "心态与情绪", translation: "Searching, searching, cold and clear, desolate and miserable."),
        Quote(text: "乍暖还寒时候，最难将息。", author: "李清照", category: "健康与生活", translation: "When it is suddenly warm and then cold again, it is hardest to rest."),
        Quote(text: "三杯两盏淡酒，怎敌他、晚来风急？", author: "李清照", category: "心态与情绪", translation: "Three cups and two lamps of light wine, how can they resist the urgent evening wind?"),
        Quote(text: "雁过也，正伤心，却是旧时相识。", author: "李清照", category: "心态与情绪", translation: "The wild geese pass by, just when I am sad, but they are old acquaintances."),
        Quote(text: "满地黄花堆积，憔悴损，如今有谁堪摘？", author: "李清照", category: "心态与情绪", translation: "Yellow flowers pile up on the ground, withered and damaged; now who is worthy to pick them?"),
        Quote(text: "守着窗儿，独自怎生得黑？", author: "李清照", category: "独处与内省", translation: "Guarding the window, how can I bear the darkness alone?"),
        Quote(text: "梧桐更兼细雨，到黄昏、点点滴滴。", author: "李清照", category: "心态与情绪", translation: "Phoenix trees plus fine rain, until dusk, drop by drop."),
        Quote(text: "这次第，怎一个愁字了得！", author: "李清照", category: "心态与情绪", translation: "This situation, how can one word 'sorrow' suffice!"),
        Quote(text: "生当作人杰，死亦为鬼雄。", author: "李清照", category: "勇气与坚持", translation: "Live as a hero among men; die as a champion among ghosts."),
        Quote(text: "至今思项羽，不肯过江东。", author: "李清照", category: "勇气与坚持", translation: "To this day I think of Xiang Yu, unwilling to cross the eastern river."),
        Quote(text: "昨夜雨疏风骤，浓睡不消残酒。", author: "李清照", category: "健康与生活", translation: "Last night the rain was sparse and the wind sudden; deep sleep did not dispel the remaining wine."),
        Quote(text: "试问卷帘人，却道海棠依旧。", author: "李清照", category: "心态与情绪", translation: "I ask the curtain-roller, who says the crabapple is still the same."),
        Quote(text: "知否，知否？应是绿肥红瘦。", author: "李清照", category: "人生智慧", translation: "Do you know? Do you know? It should be green fat and red thin."),
        Quote(text: "莫道不销魂，帘卷西风，人比黄花瘦。", author: "李清照", category: "爱情与婚姻", translation: "Do not say it is not soul-stirring; the west wind rolls up the curtain, people are thinner than yellow flowers."),
        Quote(text: "一种相思，两处闲愁。", author: "李清照", category: "爱情与婚姻", translation: "One kind of longing, two places of idle sorrow."),
        Quote(text: "此情无计可消除，才下眉头，却上心头。", author: "李清照", category: "爱情与婚姻", translation: "This feeling cannot be eliminated; just off the eyebrows, but on the heart."),
        Quote(text: "物是人非事事休，欲语泪先流。", author: "李清照", category: "心态与情绪", translation: "Things are the same but people are not; wanting to speak, tears flow first."),
        Quote(text: "只恐双溪舴艋舟，载不动许多愁。", author: "李清照", category: "心态与情绪", translation: "I fear only that the small boat at Shuangxi cannot carry so much sorrow."),
        Quote(text: "千古风流八咏楼，江山留与后人愁。", author: "李清照", category: "人生智慧", translation: "The eternal charm of the Bayong Tower; rivers and mountains leave sorrow for later generations."),
        Quote(text: "水通南国三千里，气压江城十四州。", author: "李清照", category: "人生智慧", translation: "Water connects the southern country for three thousand miles; pressure covers fourteen states of the river city."),
        Quote(text: "何须浅碧深红色，自是花中第一流。", author: "李清照", category: "自信与成长", translation: "Why need light green or deep red? It is naturally the first class among flowers."),
        Quote(text: "梅定妒，菊应羞，画阑开处冠中秋。", author: "李清照", category: "自信与成长", translation: "Plums must be jealous, chrysanthemums should be ashamed; where the painted railing opens, it crowns mid-autumn."),
        Quote(text: "骚人可煞无情思，何事当年不见收。", author: "李清照", category: "人生智慧", translation: "The poet could be so heartless; why was it not collected back then?"),
        Quote(text: "薄雾浓云愁永昼，瑞脑消金兽。", author: "李清照", category: "心态与情绪", translation: "Thin mist and thick clouds sorrow the long day; amber incense melts in the golden beast."),
        Quote(text: "佳节又重阳，玉枕纱厨，半夜凉初透。", author: "李清照", category: "健康与生活", translation: "The festival is again Double Ninth; jade pillow, gauze kitchen, midnight coolness first penetrates."),
        Quote(text: "东篱把酒黄昏后，有暗香盈袖。", author: "李清照", category: "健康与生活", translation: "After dusk drinking by the eastern fence, there is a hidden fragrance filling the sleeves."),
        Quote(text: "枕上诗书闲处好，门前风景雨来佳。", author: "李清照", category: "学习与进步", translation: "Poetry and books on the pillow are good in leisure; the scenery before the door is fine when rain comes."),
        Quote(text: "终日向人多酝藉，木犀花。", author: "李清照", category: "人生智慧", translation: "All day toward people it is rich and restrained, the osmanthus flower."),
        Quote(text: "天上星河转，人间帘幕垂。", author: "李清照", category: "人生智慧", translation: "The star river in heaven turns; the curtains in the human world hang down."),
        Quote(text: "凉生枕簟泪痕滋，起解罗衣聊问夜何其。", author: "李清照", category: "心态与情绪", translation: "Coolness grows on the pillow and mat, tear stains increase; getting up to untie silk clothes, casually asking how the night is."),
        Quote(text: "共赏金尊沉绿蚁，莫辞醉，此花不与群花比。", author: "李清照", category: "人际关系", translation: "Appreciate together the golden cup sinking green ants; do not refuse to be drunk, this flower does not compare with other flowers."),
        Quote(text: "十二楼中尽晓妆，望仙楼上望君王。", author: "薛逢", category: "爱情与婚姻", translation: "In the twelve towers all do morning makeup; on the Immortal-Gazing Tower gazing at the king."),
        Quote(text: "锁衔金兽连环冷，水滴铜龙昼漏长。", author: "薛逢", category: "独处与内省", translation: "The lock holds the cold golden beast chain; water drops from the copper dragon, the day clepsydra is long."),
        Quote(text: "云髻罢梳还对镜，罗衣欲换更添香。", author: "薛逢", category: "健康与生活", translation: "The cloud bun stops combing and faces the mirror again; silk clothes want to be changed, adding more fragrance."),
        Quote(text: "遥窥正殿帘开处，袍袴宫人扫御床。", author: "薛逢", category: "职场与事业", translation: "Peeping afar at the main hall where the curtain opens; palace people in robes and trousers sweep the imperial bed."),
        Quote(text: "誓扫匈奴不顾身，五千貂锦丧胡尘。", author: "陈陶", category: "勇气与坚持", translation: "Vowing to sweep away the Xiongnu regardless of self; five thousand sables and brocades perish in barbarian dust."),
        Quote(text: "可怜无定河边骨，犹是春闺梦里人。", author: "陈陶", category: "爱情与婚姻", translation: "Pitiful bones by the Wuding River; they are still the people in the spring boudoir's dreams."),
        Quote(text: "Believe you can and you're halfway there.", author: "Theodore Roosevelt", category: "自信与成长", translation: "相信你能做到，你就已经成功了一半。"),
        Quote(text: "Do what you can, with what you have, where you are.", author: "Theodore Roosevelt", category: "行动与执行", translation: "用你所拥有的，在你所在的地方，做你能做的。"),
        Quote(text: "It is hard to fail, but it is worse never to have tried to succeed.", author: "Theodore Roosevelt", category: "失败与挫折", translation: "失败是艰难的，但从未尝试成功更糟糕。"),
        Quote(text: "Keep your eyes on the stars, and your feet on the ground.", author: "Theodore Roosevelt", category: "梦想与目标", translation: "眼睛盯着星星，脚踏实地。"),
        Quote(text: "Nobody cares how much you know, until they know how much you care.", author: "Theodore Roosevelt", category: "人际关系", translation: "没人在乎你知道多少，直到他们知道你有多在乎。"),
        Quote(text: "Far and away the best prize that life has to offer is the chance to work hard at work worth doing.", author: "Theodore Roosevelt", category: "职场与事业", translation: "生活提供的最好的奖赏是有机会在值得做的工作中努力工作。"),
        Quote(text: "The only man who never makes a mistake is the man who never does anything.", author: "Theodore Roosevelt", category: "行动与执行", translation: "从不犯错的人是从不做事的人。"),
        Quote(text: "With self-discipline most anything is possible.", author: "Theodore Roosevelt", category: "健康与生活", translation: "有了自律，几乎所有事情都是可能的。"),
        Quote(text: "The best executive is the one who has sense enough to pick good men to do what he wants done, and self-restraint enough to keep from meddling with them while they do it.", author: "Theodore Roosevelt", category: "领导力", translation: "最好的管理者有足够的判断力挑选好人来做他想做的事，并有足够的自制力在他们做事时不干涉。"),
        Quote(text: "If you could kick the person in the pants responsible for most of your trouble, you wouldn't sit for a month.", author: "Theodore Roosevelt", category: "人生智慧", translation: "如果你能踢那个对你的大部分麻烦负责的人，你一个月都不会坐下。"),
        Quote(text: "Speak softly and carry a big stick; you will go far.", author: "Theodore Roosevelt", category: "沟通与表达", translation: "轻声说话，拿着大棒；你会走得更远。"),
        Quote(text: "Knowing what's right doesn't mean much unless you do what's right.", author: "Theodore Roosevelt", category: "责任与担当", translation: "知道什么是对的并不重要，除非你做了对的事。"),
        Quote(text: "In any moment of decision, the best thing you can do is the right thing, the next best thing is the wrong thing, and the worst thing you can do is nothing.", author: "Theodore Roosevelt", category: "选择与决策", translation: "在任何决定的时刻，你能做的最好的事是做正确的事，其次是做错的事，最糟糕的是什么都不做。"),
        Quote(text: "The boy who is going to make a great man must not make up his mind merely to overcome a thousand obstacles, but to win in spite of a thousand repulses and defeats.", author: "Theodore Roosevelt", category: "勇气与坚持", translation: "要成为伟大人物的男孩，不能仅仅下定决心克服一千个障碍，而是要在遭受一千次拒绝和失败之后仍然获胜。"),
        Quote(text: "Nothing in the world is worth having or worth doing unless it means effort, pain, difficulty.", author: "Theodore Roosevelt", category: "奋斗与拼搏", translation: "世界上没有什么值得拥有或值得做的，除非它意味着努力、痛苦和困难。"),
        Quote(text: "Character, in the long run, is the decisive factor in the life of an individual and of nations alike.", author: "Theodore Roosevelt", category: "自信与成长", translation: "从长远来看，品格是个人和民族生活中的决定性因素。"),
        Quote(text: "Order without liberty and liberty without order are equally destructive.", author: "Theodore Roosevelt", category: "自由与独立", translation: "没有自由的秩序和没有秩序的自由同样是破坏性的。"),
        Quote(text: "To educate a man in mind and not in morals is to educate a menace to society.", author: "Theodore Roosevelt", category: "学习与进步", translation: "只培养心智而不培养道德的人，是在教育社会的威胁。"),
        Quote(text: "I am a part of everything that I have read.", author: "Theodore Roosevelt", category: "学习与进步", translation: "我是我所读过的一切的一部分。"),
        Quote(text: "The most important single ingredient in the formula of success is knowing how to get along with people.", author: "Theodore Roosevelt", category: "人际关系", translation: "成功公式中最重要的单一成分是如何与人相处。"),
        Quote(text: "Old age is like everything else. To make a success of it, you've got to start young.", author: "Theodore Roosevelt", category: "健康与生活", translation: "老年就像其他一切一样。要取得成功，你必须从年轻开始。"),
        Quote(text: "Courtesy is as much a mark of a gentleman as courage.", author: "Theodore Roosevelt", category: "自信与成长", translation: "礼貌和勇气一样是绅士的标志。"),
        Quote(text: "People don't care how much you know until they know how much you care.", author: "Theodore Roosevelt", category: "人际关系", translation: "人们不在乎你知道多少，直到他们知道你有多在乎。"),
        Quote(text: "A man who has never gone to school may steal from a freight car; but if he has a university education, he may steal the whole railroad.", author: "Theodore Roosevelt", category: "学习与进步", translation: "从未上过学的人可能从货车偷东西；但如果他受过大学教育，他可能偷走整条铁路。"),
        Quote(text: "When you play, play hard; when you work, don't play at all.", author: "Theodore Roosevelt", category: "职场与事业", translation: "当你玩的时候，拼命玩；当你工作的时候，根本不要玩。"),
        Quote(text: "Big jobs usually go to the men who prove their ability to outgrow small ones.", author: "Theodore Roosevelt", category: "职场与事业", translation: "大工作通常给那些证明自己有能力超越小工作的人。"),
        Quote(text: "I don't pity any man who does hard work worth doing. I admire him. I pity the creature who does not work, at whichever end of the social scale he may regard himself as being.", author: "Theodore Roosevelt", category: "奋斗与拼搏", translation: "我不怜悯任何做值得做的艰苦工作的人。我钦佩他。我怜悯不工作的人，无论他认为自己在社会阶层的哪一端。"),
        Quote(text: "I am only an average man but, by George, I work harder at it than the average man.", author: "Theodore Roosevelt", category: "奋斗与拼搏", translation: "我只是一个普通人，但是，天哪，我比普通人更努力工作。"),
        Quote(text: "No man is above the law and no man is below it: nor do we ask any man's permission when we ask him to obey it.", author: "Theodore Roosevelt", category: "责任与担当", translation: "没有人凌驾于法律之上，也没有人低于法律：当我们要求一个人遵守法律时，我们也不征求任何人的许可。"),
    ]

    private static let quotes_batch_f: [Quote] = [
        Quote(text: "Rhetoric is a poor substitute for action, and we have trusted only to rhetoric. If we are really to be a great people, we must not merely talk; we must act big.", author: "Theodore Roosevelt", category: "沟通与表达", translation: "修辞是行动的拙劣替代品，我们只信任修辞。如果我们真的要成为一个伟大的人民，我们不仅必须说话；我们必须大胆行动。"),
        Quote(text: "Walk softly and carry a big stick.", author: "Theodore Roosevelt", category: "沟通与表达", translation: "轻声走路，拿着大棒。"),
    ]

    private static let quotes_batch_h: [Quote] = [
        Quote(text: "真正的学习，从不需要别人催促。", author: "佚名", category: "行动与执行", translation: "True learning never needs urging from others."),
