        Quote(text: "每天一点学习，一年后你会感谢自己。", author: "佚名", category: "行动与执行", translation: "A little learning every day, and you will thank yourself in a year."),
        Quote(text: "学习的最高境界，是忘记自己在学习。", author: "佚名", category: "行动与执行", translation: "The highest realm of learning is forgetting you are doing it."),
