        Quote(text: "学习让你和世界建立更深的连接。", author: "佚名", category: "行动与执行", translation: "learning lets you build deeper connections with the world."),
        Quote(text: "学习不是一时的热情，而是一世的坚持。", author: "谚语", category: "行动与执行", translation: "learning is not momentary passion, but lifelong persistence."),
        Quote(text: "学习让你明白，慢就是快。", author: "佚名", category: "行动与执行", translation: "learning teaches you that slow is fast."),
