        Quote(text: "真正的分享，从不需要别人催促。", author: "谚语", category: "独处与内省", translation: "True sharing never needs urging from others."),
        Quote(text: "分享是一种投资，回报可能迟到，但不会缺席。", author: "Trigin", category: "独处与内省", translation: "sharing is an investment; returns may be late, but they will not be absent."),
