        Quote(text: "每天一点分享，一年后你会感谢自己。", author: "佚名", category: "独处与内省", translation: "A little sharing every day, and you will thank yourself in a year."),
        Quote(text: "分享的最高境界，是忘记自己在分享。", author: "佚名", category: "独处与内省", translation: "The highest realm of sharing is forgetting you are doing it."),
