        Quote(text: "领导是一种智慧，智慧来自实践。", author: "佚名", category: "责任与担当", translation: "leadership is wisdom, and wisdom comes from practice."),
        Quote(text: "真正的负责，从不需要别人催促。", author: "佚名", category: "独处与内省", translation: "True responsibility never needs urging from others."),
